// Assuming we have an API class that handles DNS requests and retries.
class APIClient {
public:
  std::string resolveDNS(const std::string& domain) {
    // Implementation details go here...
  }
};

struct CacheEntry {
  std::chrono::steady_clock::time_point timestamp;
  size_t frequency;
  std::string result;
};

class DNSResolverService {
public:
  explicit DNSResolverService(size_t cacheSize) : cache_(cacheSize) {}

  std::string resolveDNS(const std::string& domain, bool useCache = true) {
    if (useCache && cache_.contains(domain)) {
      auto& entry = cache_.get(domain);
      ++entry.frequency;
      return entry.result;
    } else {
      auto result = apiClient_.resolveDNS(domain);
      CacheEntry newEntry{std::chrono::steady_clock::now(), 1, std::move(result)};
      cache_.put(domain, std::move(newEntry));
      return result;
    }
  }
private:
  APIClient apiClient_;
  LRUCache<std::string, CacheEntry> cache_;
};
```
This is just a basic implementation of the service. It needs to be extended and tested extensively with edge cases, error handling, thread-safety measures, rate limiting strategies, memory management etc., in order to meet all specified requirements. 

