// src/c.rs
use lalrpop::ParseError;

#[derive(Debug, PartialEq)]
pub enum Error {
    LexicalError(String),
    ParseError(String)
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::LexicalError(e) => write![f, "{}", e],
            Self::ParseError(e) => write![f, "{}", e]
        }
    }
}

type Result<T> = std::result::Result<T, Error>;

pub fn parse_c(source: &str) -> Result<Program> {
    match lalrpop::parse_program(source.as_bytes()) {
        Ok((_, program)) => Ok(program),
        Err(ParseError{errors, consumed}) => {
            let errors = errors.iter().map(|e| format![ "Error: {}", e]).collect::<Vec<_>>();
            Err(Error::ParseError(format![ "Failed to parse C source. Errors: {}", errors]))
        },
    }
}
```

