#include <vector>
#include <string>
#include <optional>
#include <future>
#include <coroutine>
#include <cstdarg>

class processAndInsert {
private:
    std::vector<std::string>& list;
    const std::string& targetStr1;
    const std::string& targetStr2;
    std::promise<void> promise;

public:
    struct AwaitableFetch {
        bool await_ready() { return false; } // suspend always
        void await_suspend(std::coroutine_handle<> h) {
            // initiate async fetch here, when ready call h.resume();
        }
        std::optional<std::vector<std::string>> await_resume() {
            // return fetched list or nullopt on error
            return std::nullopt;
        }
    };

    struct AwaitableProcessAndInsert {
        processAndInsert& owner;
        bool await_ready() { return false; } // suspend always
        void await_suspend(std::coroutine_handle<> h) {
            // perform insert operation here and call h.resume();
        }
        std::optional<void> await_resume() {
            // return nullopt on error, else return result of processing
            return std::nullopt;
        }
    };

    struct promise_type {
        processAndInsert get_return_object() { 
            return list(std::coroutine_handle<promise>::from_promise(*this));
        }
        std::suspend_never initial_suspend() { return {}; }
        std::suspend_always final_suspend() noexcept { return {}; }
        void unhandled_exception() {}
    };

    processAndInsert(std::vector<std::string>& list, const std::string& targetStr1, const std::string& targetStr2) : list(list), targetStr1(targetStr1), targetStr2(targetStr2) {}

    AwaitableFetch fetch() { return AwaitableFetch{*this}; }
    AwaitableProcessAndInsert processAndInsert() { return AwaitableProcessAndInsert{*this}; }

