public interface IDatabaseService
{
    Task<bool> ExecuteParameterizedQueryAsync(string connectionString, string sqlCommand, List<object> parameters);
}

public class DatabaseService : IDatabaseService
{
    private readonly IMemoryCache _memoryCache;
    public DatabaseService(IMemoryCache memoryCache) => _memoryCache = memoryCache;

    public async Task<bool> ExecuteParameterizedQueryAsync(string connectionString, string sqlCommand, List<object> parameters)
    {
        if (string.IsNullOrEmpty(connectionString)) throw new ArgumentException("Connection string cannot be null or empty");

        if (string.IsNullOrWhiteSpace(sqlCommand)) throw new ArgumentException("SQL command cannot be null, whitespace, or empty");

        if (parameters == null || parameters.Count == 0) throw new ArgumentException("Parameters cannot be null or empty");

        const int maxLength = 1000; // Replace with your actual limit

        if (sqlCommand.Length > maxLength) throw new ArgumentException($"SQL command length exceeded {maxLength} characters");

        try
        {
            using (var context = new MyDbContext(connectionString))
            {
                var cacheKey = $"{context.GetType()}_{sqlCommand}_query";
                // Checking if the query is cached in memory and return it immediately without hitting database 
                if (_memoryCache.TryGetValue(cacheKey, out object data))
                    return (bool)data;

                // Execute your SQL command with parameters here 
                var results = await context.Database.SqlQuery<object>(sqlCommand, parameters.ToArray()).ToListAsync();

                // Set the result in cache
                _memoryCache.Set(cacheKey, true);
                return true;
            }
        }
        catch (Exception ex)
        {
            // Log your exception here 
            Console.WriteLine($"Error: {ex}");

            // Retry policy would be needed to handle transient failures
            throw;
        }
    }

    private class MyDbContext : DbContext
    {
        public MyDbContext(string connectionString) : base(connectionString) {}
    }
}
