```python
from flask import Flask, request, jsonify
from sqlalchemy import create_engine, text
import logging
import requests
from functools import wraps
from werkzeug.contrib.fixers import ProxyFix
from flask_limiter import Limiter
from itsdangerous import URLSafeTimedSerializer

app = Flask(__name__)
limiter = Limiter(app, default_limits=["200 per day", "50 per hour"])
url_serializer = URLSafeTimedSerializer('SECRET_KEY')
engine = create_engine("postgresql://user:pass@localhost/dbname")

# Custom decorator to apply rate limits and handle errors
def api_endpoint(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            limiter.limit('50/minute')  # Apply a custom limit for this route
            result = func(*args, **kwargs)
            return jsonify(result), 200
        except Exception as e:
            logging.error(str(e))
            return jsonify({"message": "An error occurred"}), 500
    return wrapper

@app.route('/resource', methods=['PUT'])
@api_endpoint
def update_resource():
    data = request.json
    with engine.begin() as connection:
        query = text("UPDATE resource SET field1 = :value1 WHERE id = :id")
        connection.execute(query, value1=data['field1'], id=data['id'])

    # Integration with external system (this is just an example)
    try:
        response = requests.get('https://external-system.com/api', data={'token': url_serializer.dumps(data['id'])})
        if response.status_code != 200:
            raise Exception("Integration with external system failed")
    except Exception as e:
        logging.error(str(e))

    return {"message": "Resource updated successfully"}

@app.route('/resource/<int:id>', methods=['DELETE'])
@api_endpoint
def delete_resource(id):
    # Use a transaction to ensure data integrity in case of errors
    with engine.begin() as connection:
        query = text("SELECT * FROM resource WHERE id = :id")
        result = connection.execute(query, id=id).first()

        if not result:
            return {"message": "Resource not found"}, 404

        query = text("DELETE FROM resource WHERE id = :id")
        connection.execute(query, id=id)

    return {"message": "Resource deleted successfully"}

app.wsgi_app = ProxyFix(app.wsgi_app)
if __name__ == '__main__':
    app.run()
```
This is a very basic setup and does not include all the features you requested such as authentication, data validation, and more comprehensive testing, but it should give you an idea about how to structure your code for these features. 

