['Here is a high-level implementation in C# using ASP.NET Core Web API, with comments explaining what's happening at each step. This code doesn't handle actual integration with an external CDN, but demonstrates how to build the system structure. 

```CSharp
using Microsoft.AspNetCore.Mvc;
using System.Collections.Concurrent;
using System.Threading.Tasks;
using System;

// This is a basic implementation. You might need to adjust it according to your requirements.
public class UpdateServiceController : ControllerBase
{
    private readonly ConcurrentDictionary<string, SemaphoreSlim> _locks = new ConcurrentDictionary<string, SemaphoreSlim>();
    private readonly ICdnApi _cdnApi; // Implement this interface with actual CDN API calls.

    public UpdateServiceController(ICdnApi cdnApi)
    {
        _cdnApi = cdnApi;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateContent([FromBody]UpdateRequest request)
    {
        try
        {
            // Ensure atomic operations with lock.
            var semaphore = _locks.GetOrAdd(request.ElementId, key => new SemaphoreSlim(1, 1));

            await semaphore.WaitAsync();

            // Call CDN API for updating content.
            var result = await _cdnApi.UpdateContent(request);

            if (result.Success)
                return Ok(new { refreshRequired = true }); 
            else
                return BadRequest(new { errorMessage = result.ErrorMessage });
        }
        catch (Exception ex)
        {
            // Handle unexpected exceptions.
            return StatusCode(500, new { errorMessage = $"An error occurred: {ex.Message}"});
        }
        finally
        {
            semaphore?.Release();
        }
    }
}

// Define your UpdateRequest class according to the requirements of your application.
public class UpdateRequest 
{
    public string PageSectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
}
