    private DataService dataService;

    // Start streaming data from external APIs 
    @PostMapping("/start-streaming")
    public ResponseEntity<Void> startStreaming(@RequestBody ExternalApi api) {
        dataService.subscribe(api);
        return ResponseEntity.ok().build();
    }

    // Pause streaming of data
