impl std::fmt::Display for CustomErr {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        if let Some(cause) = self.cause.as_ref() {
            write_to_formatter(f, "{} (caused by: {})", self.msg, cause);
        } else {
            f.write_str(&self.msg)
        }
    }
}

impl std::error::Error for CustomErr {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        self.cause.as_ref().map(|cause| cause.as_ref())
    }
}

fn format_err_with_cause_impl(msg: &str, cause: Option<Box<dyn std::error::Error + Send + Sync>>) -> CustomErr {
    CustomErr {
        msg: msg.to_string(),
