Next, let's design our `Character` class. We will use a shared mutex to handle concurrent accesses:

```cpp
class Character {
public:
    void selectAttack(GameDifficulty difficulty) {
        auto now = std::chrono::system_clock::now();

        // Check if we can attack again.
        if (now - lastAttackTime < cooldowns[currentAttackId] * getCooldownScalingFactor(difficulty)) {
            return;
        }

        // Select a new random attack that isn't on cooldown.
        std::vector<int> availableIds = {0, 1, 2, 3, 4};
        availableIds.erase(std::remove(availableIds.begin(), availableIds.end(), currentAttackId), availableIds.end());

        int newAttackId = availableIds[rand() % availableIds.size()];

        // Fetch attack details from the database API.
        std::optional<Attack> newAttack;
        {
            std::shared_lock lock(mutex);
            newAttack = api->getAttack(newAttackId);
        }

        if (newAttack) {
            currentAttackId = newAttackId;
            lastAttackTime = now;
            // Log the attack.
            logger << "Character has selected attack: " << newAttack->name << std::endl;
        } else {
            // Handle network error...
        }
    }
private:
    double getCooldownScalingFactor(GameDifficulty difficulty) {
        switch (difficulty) {
            case GameDifficulty::EASY: return 1.0;
            case GameDifficulty::MEDIUM: return 2.0;
            case GameDifficulty::HARD: return 3.0;
        }
    }

private:
    std::shared_mutex mutex;
    AttackDatabaseAPI* api;
    Logger logger;
    int currentAttackId = 0;
    std::chrono::time_point<std::chrono::system_clock> lastAttackTime = std::chrono::system_clock::now();
    std::unordered_map<int, double> cooldowns = {{0, 12.0}, {1, 15.0}, {2, 20.0}, {3, 24.0}, {4, 30.0}}; // Cooldowns in seconds
};
```

This is a high-level design and won't compile by itself. You would need to implement the RESTful API fetching and logging mechanisms yourself. Also you might want to consider using more efficient data structures for managing cooldowns and attacks, such as `std::unordered_map` or custom hash maps.
