#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure to represent a transaction
typedef struct Transaction {
    char* data;
    double amount;
} Transaction;

// Global variables for tracking average and count
double total = 0.0;
int count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* processTransaction(void *args) {
    Transaction *trans = (Transaction*) args;

    // Parse transaction data here...
    double amount = 0.0;

    pthread_mutex_lock(&lock);
        total += amount;
        count++;

        if(count % 3 == 0) {
            printf("Average of last three transactions: %f\n", total / count);
        }
    pthread_mutex_unlock(&lock);

    free(trans->data); // Remember to free allocated memory
}

int main() {
    FILE *file = fopen("log.txt", "r");
    if (file == NULL) {
        printf("Could not open file\n");
        return 1;
    }

    char buffer[256];
    while(fgets(buffer, sizeof(buffer), file)) { // Reading line by line
        Transaction *trans = malloc(sizeof(Transaction)); // Dynamically allocate memory for transaction data

        if (trans == NULL) {
            printf("Memory allocation failed\n");
            return 1;
        }

        trans->data = strdup(buffer); // Make a copy of the buffer to ensure it doesn't get overwritten by fgets in next iteration

        pthread_t thread;
        int result = pthread_create(&thread, NULL, processTransaction, trans);
        if (result != 0) {
            printf("Thread creation failed\n");
            return 1;
        }
    }

    fclose(file); // Don't forget to close the file
    return 0;
}
```
