['Developing a full-blown C library as per the specifications is quite extensive and beyond the capacity of this assistant. However, I can provide you with a starting point for your codebase by demonstrating how you might set up a basic C project structure and add some functionality to handle CSV files.

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

// Define a struct for our data
typedef struct {
    char **data;
    int size;
} CSVData;

// Function to load a CSV file into memory
CSVData* read_csv(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    CSVData *data = malloc(sizeof(CSVData));
    data->data = malloc(1024 * sizeof(char*)); // Start with a small size for performance reasons
    data->size = 0;

    char line[512];
    while (fgets(line, sizeof(line), file)) {
        int len = strlen(line);
        if (len > 0 && line[len - 1] == '\n')
            line[--len] = '\0'; // Remove trailing newline character

        data->data[data->size++] = strdup(line);
    }

    fclose(file);
    return data;
}

// Function to query a CSVData struct
void query_csv_data(CSVData *data, const char *query) {
    // For now, just print all lines that contain the query string
    for (int i = 0; i < data->size; ++i) {
        if (strstr(data->data[i], query)) {
            printf("%s\n", data->data[i]);
        }
    }
}

// Function to free a CSVData struct
void free_csv_data(CSVData *data) {
    for (int i = 0; i < data->size; ++i) {
        free(data->data[i]);
    }
    free(data->data);
    free(data);
}

int main() {
    CSVData *data = read_csv("test.csv");
    if (data == NULL) return 1;

    query_csv_data(data, "query");
    free_csv_data(data);
    return 0;
