#include <time.h>
#include <unistd.h>
#include <pthread.h>

// Global variables
pthread_mutex_t lock;
FILE* logfile;
char* directory_path = "/your/directory"; // Modify this to your target directory

void* backup(void* arg) {
    DIR *d;
    struct dirent *dir;
    d = opendir(directory_path);

    if (d) {
        while ((dir = readdir(d)) != NULL) {
            struct stat stbuf;
            char file_path[1024];

            snprintf(file_path, sizeof file_path, "%s/%s", directory_path, dir->d_name);

            if (stat(file_path, &stbuf) == -1) {
                fprintf(logfile, "Failed to stat %s: %m\n", file_path);
                continue;
            }

            pthread_mutex_lock(&lock);

            // Process changes here. 
            // For example: Save to a CSV file or handle asynchronously, etc...

            pthread_mutex_unlock(&lock);
        }

        closedir(d);
    }

    return NULL;
}

int main() {
    logfile = fopen("log.txt", "a"); // Open a file to write logs
    if (logfile == NULL) {
        perror("Failed to open logfile: ");
        return 1;
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, backup, NULL);

    // Wait for the backup thread to finish
    pthread_join(thread_id, NULL);

    fclose(logfile);
}
```
