    if(!json_is_string(access_token)) {
        fprintf(stderr, "Invalid 'access_token'\n");
        return -1;
    }

    json_t *expires_in = json_object_get(root, "expires_in");
    if(!json_is_integer(expires_in)) {
        fprintf(stderr, "Invalid 'expires_in'\n");
        return -1;
    }

    json_t *token_type = json_object_get(root, "token_type");
    if(!json_is_string(token_type) || strcmp(json_string_value(token_type), "Bearer")) {
        fprintf(stderr, "Invalid 'token_type'\n");
        return -1;
    }

    json_t *refresh_token = json_object_get(root, "refresh_token");
    if(refresh_token && !json_is_string(refresh_token)) {
        fprintf(stderr, "Invalid 'refresh_token'\n");
        return -1;
    }

    CURL *curl = curl_easy_init();
    if(!curl) {
        fprintf(stderr, "Failed to initialize cURL\n");
        return -1;
    }

    // Configure and perform the request here...

