                while ((graph = _formatter.Deserialize(stream)) != null)
                {
                    // Process deserialized data...
                }
            }
            catch (Exception ex) when (!(ex is SerializationException))
            {
                _logger.LogError(ex, "Failed to process file: {FilePath}", filePath);

                // Handle error here or retry as needed...
            }
        }
    }
}
```

In the above code snippet, we use a `BinaryFormatter` to deserialize data from a binary log file. If any deserialization exceptions are thrown (other than `SerializationException`), we catch them and log an error message using the injected `ILogger<T>` instance.

