            throw 'Unable to update config: rate limit reached or missing password';
        }

        const encryptedPasswordResponse = await axios.post(encryptUrl, { password: newPassword });
        rateLimit--; // Decrement rate limit after each request

        const sedCommand = `sed -i 's/password=.*/password=${encryptedPasswordResponse.data.encrypted}/' /etc/kickstart-config`;

