```cpp
#include <json/json.h>
#include <string>

bool validateOauthToken(const std::string& json_str) {
    Json::Value root;
    Json::Reader reader;

    bool parsingSuccessful = reader.parse(json_str, root);
    if (!parsingSuccessful) {
        return false;
    }

    const std::string requiredKeys[4] = {"access_token", "expires_in", "token_type", "refresh_token"};
    for (const auto& key : requiredKeys) {
        if (!root.isMember(key)) {
            return false;
        }
    }

    if (root["token_type"].asString() != "Bearer") {
        return false;
    }

    int expiresIn = root["expires_in"].asInt();
    if (expiresIn < 0) {
        return false;
    }

    // Additional checks on refresh_token could be done here.

    return true;
}
```
This function assumes that you have the `jsoncpp` library installed for handling JSON parsing in C++. 

