['Here's a rough sketch of how you might implement this in C++ using std::thread, std::mutex, and std::condition_variable for concurrency control. Note that due to simplicity, error handling and fallback mechanisms are not included here. The code requires C++14 or later.

```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>
#include <chrono>
#include <condition_variable>

class CombatEntity {
public:
    struct AttackPattern {
        std::string name;
        int executionTime;
        int cooldownDuration;
        bool isOnCooldown = false;
        std::thread cooldownThread;
    };

private:
    std::vector<AttackPattern> attackPatterns;
    std::mutex mtx;
    std::condition_variable cv;
    int currentCooldown = 0;

public:
    CombatEntity(const std::vector<AttackPattern>& patterns) : attackPatterns(patterns) {}

    void executeAttack() {
        std::unique_lock<std::mutex> lock(mtx);

        if (currentCooldown > 0) {
            std::cout << "Entity is on cooldown for " << currentCooldown << " seconds.\n";
            return;
        }

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, attackPatterns.size() - 1);
        int index = dis(gen);
        auto& pattern = attackPatterns[index];

        if (!pattern.isOnCooldown) {
            pattern.cooldownThread = std::thread([this, &pattern](){
                currentCooldown = pattern.cooldownDuration;

                while (currentCooldown > 0) {
                    --currentCooldown;
                    std::this_thread::sleep_for(std::chrono::seconds(1));
                }

                std::lock_guard<std::mutex> guard(mtx);
                pattern.isOnCooldown = false;
                cv.notify_all();
            });

            pattern.cooldownThread.detach();
        }

        cv.wait(lock, [this](){ return currentCooldown == 0; });
    }

    void updateCooldownDuration(const std::string& attackName, int newDuration) {
        for (auto& pattern : attackPatterns) {
            if (pattern.name == attackName) {
                pattern.cooldownDuration = newDuration;
                return;
            }
        }
    }
};
```
This code is a simplified implementation and doesn't include all the features you requested, such as error handling, external dependency integration, or scalability for a large number of attack patterns. Also, this class does not provide any public methods to get the current state of attacks since it should only expose necessary functionality while hiding internal details for encapsulation purpose.
