```csharp
using System;
using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using System.Net.Http;

[ApiController]
[Route("api/[controller]")]
public class PreferencesController : ControllerBase
{
    private readonly IMemoryCache _cache;
    private readonly IHttpClientFactory _clientFactory;

    public PreferencesController(IMemoryCache memoryCache, IHttpClientFactory clientFactory)
    {
        _cache = memoryCache;
        _clientFactory = clientFactory;
    }

    [HttpGet]
    public async Task<ActionResult> GetPreference([FromQuery] string key)
    {
        if (!_cache.TryGetValue(key, out var preference))
        {
            var request = new HttpRequestMessage(HttpMethod.Get, $"api/preference?key={key}");
            var client = _clientFactory.CreateClient("preferencesService");
            var response = await client.SendAsync(request);

            if (response.IsSuccessStatusCode)
                preference = await response.Content.ReadAsStringAsync();
        }

        return Ok(preference);
    }

    [HttpPost]
    public async Task<ActionResult> SetPreference([FromQuery] string key, [FromBody] object value)
    {
        var request = new HttpRequestMessage(HttpMethod.Post, $"api/preference?key={key}")
        {
            Content = new StringContent(value.ToString(), Encoding.UTF8, "application/json")
        };

        var client = _clientFactory.CreateClient("preferencesService");
        var response = await client.SendAsync(request);

        if (response.IsSuccessStatusCode)
            _cache.Set(key, value, new MemoryCacheEntryOptions().SetSlidingExpiration(TimeSpan.FromMinutes(5)));

        return Ok();
    }
}
```
