  // If the script has already been loaded, return a resolved Promise immediately.
  if (loadedScripts.has(src)) return Promise.resolve();

  const script = document.createElement('script');
  script.type = 'text/javascript';
  script.async = true;
  script.defer = true;
  script.integrity = SCRIPT_INTEGRITY;
  script.src = src;

  const promise = new Promise((resolve, reject) => {
    script.onload = resolve;
    script.onerror = () => reject(new Error(`Failed to load script: ${src}`));
  });

  document.body.appendChild(script);

  try {
    await promise; // Wait for the script to load or fail.

    loadedScripts.set(src, true); // Store that the script has been successfully loaded.

    console.log('Loaded script:', src);
  } catch (error) {
    console.error('Failed to load script:', error);

    throw error; // Rethrow for caller to handle as needed.
  }
}
```
This function is designed to be easy to extend and integrate with other script types or external services in the future. However, it doesn't directly integrate with a CDN yet - that would require specifics based on which CDN you are using.

