```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class NetworkService {

    private Selector selector;
    private InetSocketAddress listenAddress;

    public void start() throws IOException {
        this.selector = Selector.open();
        ServerSocketChannel serverChannel = ServerSocketChannel.open();
        serverChannel.configureBlocking(false);
        serverChannel.socket().bind(listenAddress);
        serverChannel.register(this.selector, SelectionKey.OP_ACCEPT);

        while (true) {
            this.selector.select();  // Block until ready for at least one operation
            Set<SelectionKey> selectedKeys = this.selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();
                if (key.isAcceptable()) {
                    this.accept(key);
                } else if (key.isReadable()) {
                    read(key);
                } else if (key.isWritable()) {
                    write(key);
                }
                keyIterator.remove();  // Remove the current key so we don't process it again
            }
        }
    }

    private void accept(SelectionKey key) throws IOException {
        ServerSocketChannel serverChannel = (ServerSocketChannel) key.channel();
        SocketChannel clientChannel = serverChannel.accept();
        clientChannel.configureBlocking(false);
        clientChannel.register(this.selector, SelectionKey.OP_READ | SelectionKey.OP_WRITE);
    }

    private void read(SelectionKey key) throws IOException {
        SocketChannel client = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        int numRead = -1;
        if ((numRead = client.read(buffer)) == -1) {  // The channel has reached EOF
            this.endSession(key);
        } else {
            // Process received data...
        }
    }

    private void write(SelectionKey key) throws IOException {
        SocketChannel client = (SocketChannel) key.channel();
        ByteBuffer buffer = (ByteBuffer) key.attachment();
        if (!buffer.hasRemaining()) {  // The data has been fully written out to the channel
            this.endSession(key);
        } else {
            client.write(buffer);
        }
    }

    private void endSession(SelectionKey key) throws IOException {
        SocketChannel client = (SocketChannel) key.channel();
        client.close();  // Close the connection to this client
    }
}
```
In a production environment, you'd need to add many more elements including: proper exception handling, authentication, connection pooling, logging, metrics and alerting, service discovery, load balancing, timeouts, fallbacks and circuit breaking. Also consider using an existing framework or library for these tasks, as writing all that from scratch will be complex and error-prone.
