```python
class FIFOEvictionPolicy(EvictionPolicy):
    # The queue is used to keep track of which items are being accessed recently and can be evicted when necessary.
    def __init__(self, max_size: int = 1024):
        self._queue = deque(maxlen=max_size) 

    def should_evict(self, key: str) -> bool:
        return len(self._queue) == self._queue.maxlen

    def accessed(self, key: str):
        if key not in self._queue:
            self._queue.append(key) 
