        self._server_adapters = server_adapters 
        self._cache = {}
        self._eviction_policy = eviction_policy

    async def get_avatar(self, user_id: str) -> Optional[Avatar]:
        if user_id in self._cache: 
            return self._cache[user_id]

        for server_adapter in self._server_adapters:
            avatar = await server_adapter.get_avatar(user_id)

            if avatar is not None:
                self._add_to_cache(user_id, avatar) 
                return avatar

        return None 

    def _add_to_cache(self, key: str, value: Avatar):
        # If cache size exceeds limit and policy allows eviction, remove the oldest element.
        if len(self._cache) >= self._max_size and self._eviction_policy.should_evict(key):
            self._remove_oldest() 

        self._cache[key] = value
