const express = require('express');
const axios = require('axios');
const LRU = require('lru-cache');

// Initialize cache
let options = {
  max: 500,            // size of the cache
  length: function (n, key) { return n * 2 + key.length },
  dispose: function (key, n) { n.close() },  
  maxAge: 1000 * 60 * 60    // in ms
}
const cache = new LRU(options);

// Initialize express app
const app = express();
app.use(express.json());

let configs = [ /* add your log sources configuration here */ ];

app.get('/logs', async (req, res) => {
  try {
    let results = await Promise.all(configs.map(async ({ url, token }) => {
      // Check cache first
      if (!cache.has(url)) {
        const response = await axios({ method: 'get', url, headers: {'Authorization': `Bearer ${token}`}});
        cache.set(url, response.data);
      }

      return cache.peek(url);
    }));

    // Sort logs by timestamp and filter based on severity level
    let allLogs = results.reduce((accumulator, currentValue) => accumulator.concat(currentValue), []).sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

    // Filter by severity threshold (here's a placeholder implementation)
