// Function that computes the MD5 hash of a given file path securely
unsigned char* computeMD5(const char *filename, int *resultSize){
    unsigned char c[MD5_DIGEST_LENGTH];
    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];
    FILE *inFile = fopen (filename, "rb");
    if (inFile == NULL) return NULL; // File access error...

    MD5_Init (&mdContext);
    while ((bytes = fread (data, 1, 1024, inFile)) != 0){
        MD5_Update (&mdContext, data, bytes);
    }
    MD5_Final (c, &mdContext);
    *resultSize = MD5_DIGEST_LENGTH;

    return c;
} 
```
