private static extern int computeMD5(string filePath, IntPtr resultSize);

public static byte[] ComputeHash(string filename) {
    IntPtr size = Marshal.AllocHGlobal(Marshal.SizeOf<int>());
    try {
        var ptr = computeMD5(filename, size);
        int len = Marshal.ReadInt32(size);

        byte[] result = new byte[len];
        Marshal.Copy(ptr, result, 0, len);

        return result;
    } finally {
        Marshal.FreeHGlobal(size);
