# Import necessary modules. This is an example and does not include all dependencies.
from abc import ABC, abstractmethod
import threading
import requests

class CloudService(ABC):
    @abstractmethod
    def submit_job(self, job): pass

    @abstractmethod
    def get_status(self, job_id): pass

# Implement for each cloud service. This is an example and does not include all attributes or methods.
class AWSBatchService(CloudService):
    def __init__(self, access_key, secret_access_key):
        self.client = boto3.client('batch', aws_access_key_id=access_key, aws_secret_access_key=secret_access_key)

class JobOrchestrator:
    def __init__(self):
        self.services = []
        self.thread_pool = []
        self.jobs = {}  # This could be a database or other storage solution

    def add_service(self, service):
        if isinstance(service, CloudService):
            self.services.append(service)
        else:
            raise TypeError("Attempted to add an object that does not inherit from CloudService.")

    def submit_job(self, job):
        # Assuming a round-robin strategy for now
        service = self.services[len(self.jobs) % len(self.services)]
        job_id = service.submit_job(job)
        self.jobs[job_id] = {"service": service, "status": "submitted", "job": job}
        return job_id

    def get_status(self, job_id):
        if job_id in self.jobs:
            return self.jobs[job_id]["status"]
        else:
            raise KeyError("Job ID not found.")
``` 
This is a basic skeleton that outlines how to create an orchestrator that can interact with multiple cloud-based job management services. This code does not include all necessary functionality such as priority handling, dynamic resource allocation, logging, retry mechanisms and so on. Each of these features would require additional complexity and likely their own classes or methods in the system architecture.
