// Function to execute commands in a separate thread
void* executeCommand(void* command) {
  char *cmd = (char*)command;

  FILE* pipe = popen(cmd, "r");
  if (!pipe) return NULL;

  // Use a buffer to read the output of the command
  char buffer[256];
  while (!feof(pipe)) {
    if (fgets(buffer, 256, pipe) != NULL){
      syslog(LOG_INFO, "Output: %s", buffer); // Logging output
    }
  }

  pclose(pipe);
  return NULL;
}

int main() {
  curl_global_init(CURL_GLOBAL_DEFAULT); // Initialize libcurl

  int numCommands = 10;
  char* commands[numCommands]; // Array of commands to be executed concurrently

  pthread_t threads[numCommands]; // Thread array for managing multiple child processes

  for (int i = 0; i < numCommands; i++) {
    // Create a new thread for each command and pass the command as argument
    if(pthread_create(&threads[i], NULL, executeCommand, (void*)commands[i])){
      fprintf(stderr, "Error creating thread\n");
      return 1;
    }
  }

  // Wait for all threads to finish
  for (int i = 0; i < numCommands; i++) {
    pthread_join(threads[i], NULL);
  }

  curl_global_cleanup(); // Clean up libcurl when finished

  return 0;
}
```
This is just a high level pseudo-code and you would need to expand on it significantly for a production ready system. You would also need to implement your own error handling, security measures, GUI, and logging solution which I have left out for brevity. It's important to note that this will not compile as is, but it gives an idea of how such a system could be structured in C.
