1. Token Validation:
```c
#include <jansson.h>

int validate_token(const char *json) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        return -1; // Error parsing JSON
    }

    // Get required fields and validate them
    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");

    if(!json_is_string(access_token) || !json_is_integer(expires_in) || 
       !json_is_string(token_type)) {
        return -1; // Invalid field type
    }

    if(strcmp(json_string_value(token_type), "Bearer") != 0 || json_integer_value(expires_in) <= 0) {
        return -1; // Invalid token type or expiry time
    }

    // Optional field
    json_t *refresh_token = json_object_get(root, "refresh_token");
    if(refresh_token && !json_is_string(refresh_token)) {
        return -1; // Invalid refresh token
    }

    json_decref(root);
    return 0; // Success
}
```
2. External Integration:
You need to use HTTP client library like libcurl for communicating with external service. Here is a simple example of POST request using libcurl:

