#include <curl/curl.h>

CURLcode curl_post(const char *url, const char *data) {
    CURL *curl = curl_easy_init();
    if(!curl) {
        return CURLE_FAILED_INIT; // Failed to initialize libcurl
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);

    CURLcode res = curl_easy_perform(curl);

    if(res != CURLE_OK) {
