public class DataPipeline
{
    private readonly string key = "your_secret_key"; // replace with actual secret key
    private readonly string iv = "your_initialization_vector"; // replace with actual IV

    public void ProcessData(string endpoint)
    {
        try
        {
            using (WebClient client = new WebClient())
            {
                ServicePointManager.SecurityProtocol |= SecurityProtocolType.Tls12 | SecurityProtocolType.Tls11 | SecurityProtocolType.Tls;

                byte[] encryptedData = client.DownloadData(endpoint);
                byte[] decryptedData = DecryptData(encryptedData, key, iv);

                string jsonData = Encoding.UTF8.GetString(decryptedData);

                var data = JsonConvert.DeserializeObject<CustomDataStructure>(jsonData);

                // Process the data...
            }
        }
        catch (WebException webEx)
        {
            Console.WriteLine("An error occurred while receiving data: " + webEx.Message);
        }
        catch (CryptographicException cryptoEx)
        {
            Console.WriteLine("An error occurred during decryption: " + cryptoEx.Message);
        }
        catch (JsonReaderException jsonEx)
        {
            Console.WriteLine("Error parsing JSON data: " + jsonEx.Message);
        }
    }

    private byte[] DecryptData(byte[] encrypted, string key, string iv)
    {
        using (AesGcm aes = new AesGcm(Encoding.UTF8.GetBytes(key)))
        {
            var nonce = Encoding.UTF8.GetBytes(iv);

            var tag = new byte[16];
            Array.Copy(encrypted, encrypted.Length - 16, tag, 0, 16); // Assuming last 16 bytes are the tag

            var ciphertext = new byte[encrypted.Length - 16]; // Ignore the last 16 bytes which hold the tag
            Array.Copy(encrypted, 0, ciphertext, 0, encrypted.Length - 16);

            var plaintext = new byte[ciphertext.Length];

            aes.Decrypt(nonce, ciphertext, tag, plaintext);

            return plaintext;
        }
    }
}
```

