1. Task class: 
```cpp
class Task {
private:
    int taskID;
    int priorityLevel;
    std::string metadata;
public:
    Task(int id, int priority, const std::string& meta) : taskID(id), priorityLevel(priority), metadata(meta){}

    // getters and setters
};
```
2. A basic thread-safe priority queue:
```cpp
#include <queue>
#include <mutex>
#include <condition_variable>

template<typename T>
class SafePriorityQueue {
private:
    std::priority_queue<T> data;
    mutable std::mutex mtx;
    std::condition_variable cv;
public:
    void push(const T& val) {
        std::lock_guard<std::mutex> lock(mtx);
        data.push(val);
        cv.notify_one();
    }

    void waitAndPop(T& val) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !data.empty(); });
        val = data.top();
        data.pop();
    }
};
```
3. A basic worker thread:
```cpp
#include <thread>

void workerThread() {
    SafePriorityQueue<Task*> taskQueue;
    while (true) {
        Task* task = nullptr;
        taskQueue.waitAndPop(task);
        if (task != nullptr) {
            // process the task
        } else {
            // end of tasks, exit thread
            break;
        }
    }
}
```
4. For error handling and logging you can use `std::cerr` for errors and `std::clog` for general messages. For advanced logging systems like syslog or Google's gLog, consider external libraries.

