    private readonly ConnectionMultiplexer _redisConnection;
    private readonly IDatabase _cache;

    public MapService(string redisConnectionString)
    {
        _redisConnection = ConnectionMultiplexer.Connect(redisConnectionString);
        _cache = _redisConnection.GetDatabase();
    }

    [HttpPost]
    public async Task<MapConfiguration> LoadConfigurationsFromThirdPartyAPI()
    {
        MapConfiguration mapConfig;
        var cacheKey = $"api_response";

        if (!_cache.KeyExists(cacheKey))
        {
            // Apply retry policy to handle API rate limits and transient errors
            var retryPolicy = Policy.Handle<Exception>().WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

            await retryPolicy.ExecuteAsync(async () => {
                // Call the API here and handle exceptions accordingly

                mapConfig = await CallAPI();  // This is just a placeholder for actual call to API

                // Store in cache with TTL of 5 minutes
                _cache.StringSet(cacheKey, JsonConvert.SerializeObject(mapConfig), TimeSpan.FromMinutes(5));
            });
        } else {
            mapConfig = JsonConvert.DeserializeObject<MapConfiguration>(_cache.StringGet(cacheKey));
        }

        // Load local JSON configurations (you can use Newtonsoft.Json to deserialize this)
        var localConfigs = JsonConvert.DeserializeObject<List<LocalMapConfiguration>>(File.ReadAllText(_localFilePath));
        mapConfig.LocalConfigurations = localConfigs;  // Add local configurations to the main object

        return mapConfig;
    }

    private async Task<MapConfiguration> CallAPI()
    {
        // This is a placeholder for actual call to API
        throw new NotImplementedException();
    }
}
```

