from concurrent.futures import ThreadPoolExecutor

class ConfigManager:
    def __init__(self, key):
        self.key = key

    def encrypt_password(self, password):
        cipher = AES.new(self.key, AES.MODE_ECB)
        return cipher.encrypt(password)

    def decrypt_password(self, encrypted_password):
        cipher = AES.new(self.key, AES.MODE_ECB)
        return cipher.decrypt(encrypted_password).rstrip()  # Remove padding

    def replace_placeholders(self, filepath, placeholder_values):
        atomic_update_file = f"{filepath}.atomic"
        cmd = f'sed '
        for placeholder, value in placeholder_values.items():
            if isinstance(value, str):  # Ensure string values are properly escaped
                value = value.replace("'", "\'").replace('"', '\\"')
            cmd += f"-e 's/{placeholder}/{value}/g' "
        cmd += f'"{filepath}" > {atomic_update_file}'  # Atomic operation to prevent partial updates
        subprocess.run(cmd, shell=True)  
        os.rename(atomic_update_file, filepath)  # Rename atomically

class ThemeManager:
    def __init__(self):
        self.bitmaps = {}

    def update_bitmap(self, key, value):
        self.bitmaps[key] = value

    def delete_bitmap(self, key):
        del self.bitmaps[key]

    def recover_bitmap(self, key, default=None):
