['```c
#include <unistd.h>
#include <sys/wait.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *logfile;

int runInBackground(char *cmd) {
    pthread_mutex_lock(&mutex);
    logfile = fopen("execution.log", "a");

    pid_t childPID = fork();

    if (childPID == -1) {  // Fork failed
        perror("Fork failed.");
        fclose(logfile);
        pthread_mutex_unlock(&mutex);
        return 0;
    } else if (childPID == 0) {  // Child process
        int systemStatus = system(cmd);

        if (systemStatus == -1 || systemStatus == 127) {
            fprintf(logfile, "%s failed to execute.\n", cmd);
            exit(EXIT_FAILURE);  // Child exits with failure status
        } else {
            fprintf(logfile, "%s executed successfully.\n", cmd);
            exit(EXIT_SUCCESS);  // Child exits with success status
        }
    } else {  // Parent process
        int waitStatus;

        if (waitpid(childPID, &waitStatus, 0) == -1) {
            perror("Wait failed.");
            fclose(logfile);
            pthread_mutex_unlock(&mutex);
            return 0;
        }

        // Log wait status
        if (WIFEXITED(waitStatus)) {
            int exitCode = WEXITSTATUS(waitStatus);

            if (exitCode == EXIT_SUCCESS) {
                fprintf(logfile, "%s exited successfully.\n", cmd);
            } else {
                fprintf(logfile, "%s failed with code %d.\n", cmd, exitCode);
            }

            fclose(logfile);
            pthread_mutex_unlock(&mutex);
            return exitCode;  // Returns exit status of child process
        } else if (WIFSIGNALED(waitStatus)) {
            int termSignal = WTERMSIG(waitStatus);

            fprintf(logfile, "%s terminated with signal %d.\n", cmd, termSignal);
            fclose(logfile);
            pthread_mutex_unlock(&mutex);
            return 0;
        } else {
            fprintf(logfile, "Unexpected status for %s.\n", cmd);
            fclose(logfile);
            pthread_mutex_unlock(&mutex);
            return 1;
        }
    }
}
```
This C function uses `fork()` and `waitpid()` system calls to safely run a given command in the background. It is thread-safe as it locks a mutex before accessing a shared resource (the log file), ensures that each message gets written in order, and then unlocks the mutex when finished. Error handling is done at every step: fork failed, waitpid failed, unexpected child status. If an error occurs, the function logs a detailed error message to a log file and returns 0 or 1 accordingly.
']

