['Here is a basic C function that can run a command in background using fork() and wait() system calls. This code is not a fully-functional backend service, but rather an elementary demonstration of how you might execute commands asynchronously. 

```c
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>
#include <string.h>
#include <stdio.h>

int run_in_background(const char *cmd) {
    pid_t pid = fork();

    if (pid < 0) {
        fprintf(stderr, "Fork failed: %s\n", strerror(errno));
        return 0; // Failure
    } else if (pid == 0) {
        execl("/bin/sh", "sh", "-c", cmd, NULL);

        fprintf(stderr, "Execution failed: %s\n", strerror(errno));
        return 0; // Failure
    } else {
        int status = 0;
        if (waitpid(pid, &status, 0) != pid) {
            fprintf(stderr, "Wait failed: %s\n", strerror(errno));
            return 0; // Failure
        } else {
            if (!WIFEXITED(status)) {
                fprintf(stderr, "Command did not exit cleanly\n");
                return 0; // Failure
            } else {
                int exit_code = WEXITSTATUS(status);

                if (exit_code != 0) {
                    fprintf(stderr, "Command exited with code %d\n", exit_code);
                    return 0; // Failure
                } else {
                    return 1; // Success
                }
            }
        }
    }
}
```

Please note that this code is quite basic and doesn't account for many of the constraints and trade-offs you mentioned. For example, it does not implement any form of caching or network routing, nor does it handle transient failures in a graceful manner. Also, error logging is quite rudimentary as well.

