class TimescaleDB(AbstractTimeSeriesDB):
    # Implement methods for interacting with TimescaleDB

class CloudStorageService:
    def upload_data(self, data: str):
        pass

# The main pipeline 
class DataPipeline:
    def __init__(self, db: AbstractTimeSeriesDB, storage: CloudStorageService):
        self.db = db
        self.storage = storage
        self.buffer = [] # Buffer for storing incoming data points before writing to DB

    def add_data(self, data: dict):
        self.buffer.append(data)

        if len(self.buffer) >= 1000: # Adjust this threshold based on your requirements
            threading.Thread(target=self._flush_to_db).start()

    def _flush_to_db(self):
        self.db.write_points(self.buffer)
        self.storage.upload_data(str(self.buffer))
        self.buffer = [] # Clear the buffer after writing to DB and storage
``` 
