```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use tokio::net::TcpStream;
use tokio_tungstenite::accept_async;
use tokio_util::codec::Framed;
use futures::stream::StreamExt;
use crate::frame::WebSocketFrame;

pub struct WebSocketHandler {
    sessions: Arc<Mutex<HashMap<usize, Session>>>,
}

impl WebSocketHandler {
    pub fn new() -> Self {
        Self {
            sessions: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub async fn start_listening(&self, address: &str) {
        let listener = TcpListener::bind(address).await.unwrap();

        loop {
            let (stream, _) = listener.accept().await.unwrap();
            tokio::spawn(async move { self.handle_connection(stream).await });
        }
    }

    async fn handle_connection(&self, stream: TcpStream) {
        let (ws_stream, response) = accept_async(Response::from(stream)).await.unwrap();

        if let Some(session) = self.sessions.lock().unwrap().get(&response.id()) {
            session.update_stream(ws_stream);
        } else {
            let (tx, rx) = oneshot::channel();
            let session = Session::new(response.id(), ws_stream, tx);
            self.sessions.lock().unwrap().insert(session.id, session);

            tokio::spawn(async move {
                if let Err(_) = session.run().await {
                    // Handle error here
                }
            });
        }
    }
}
```

This is a simplified version and does not include all your requirements, but it gives you an idea of how to start building the system. The `Session` struct would be where you implement the logic for handling user authentication, session management, token issuance etc., while the `WebSocketHandler` manages connections from different clients.

