    ResponseEntity<Void> newPayment(@RequestBody @Valid PaymentRequest request) {
        // Handle the incoming requests, process and validate them accordingly
        var transactionId = paymentService.processTransaction(request);

        return ResponseEntity.created(URI.create("/payments/" + transactionId)).build();
    }

    @GetMapping("/payments/{id}")
    PaymentResponse getPayment(@PathVariable String id) {
