        return new PaymentResponse(paymentService.getTransactionStatus(id));
    }

    @DeleteMapping("/payments/{id}")
    ResponseEntity<Void> cancelPayment(@PathVariable String id) {
        // Cancel the payment and handle any exceptions or errors accordingly
        try {
            paymentService.cancelTransaction(id);

            return ResponseEntity.noContent().build();
