use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use chrono::prelude::*;
use backoff::Backoff;
use reqwest::Error as ReqwestError;
use log::error;
use tokio::time::interval;

type Average = f64;
type TransactionAmount = i32;

#[derive(Debug)]
struct TransactionLog {
    timestamp: DateTime<Utc>,
    amount: TransactionAmount,
}

#[derive(Clone)]
struct ProcessorState {
    pub log_window: VecDeque<TransactionLog>,
    pub average_amount: Mutex<Option<Average>>,
    backoff: Arc<Backoff>,
}

impl ProcessorState {
    fn new() -> Self {
        ProcessorState {
            log_window: VecDeque::new(),
            average_amount: Mutex::new(None),
            backoff: Arc::new(Backoff::default()),
        }
    }

    async fn process_logs(&self, logs: Vec<TransactionLog>) {
        for log in logs {
            self.average_amount
                .lock()
                .unwrap()
                .replace(self.update_average(log));
        }
    }

    fn update_average(&mut self, log: TransactionLog) -> Average {
        let current = *self.average_amount.lock().unwrap().unwrap_or(0f64);

        if self.log_window.len() == 15 {
            self.log_window.pop_front();
        }

        self.log_window.push_back(log);

        let sum: i32 = self.log_window.iter().map(|t| t.amount).sum();

        (sum as f64) / (self.log_window.len() as f64)
    }
}

#[tokio::main]
async fn main() {
    let state = Arc::new(ProcessorState::new());

    interval(Duration::from_secs(60)).for_each(|_| async move {
        loop {
            match fetch_logs().await {
                Ok(logs) => {
                    state.process_logs(&logs).await;
                    break;
                }
                Err(e) => {
                    error_notify(e);
                    std::thread::sleep(state.backoff.next_back_off());
                }
            }
        }
    });
}

async fn fetch_logs() -> Result<Vec<TransactionLog>, ReqwestError> {
    let client = reqwest::Client::new();

    let url = "https://example.com/transactions";

    let response = client.get(url).send().await?;

    let mut logs: Vec<TransactionLog> = vec![];

    for line in response.text().await?.lines() {
        let parts: Vec<&str> = line.split(';').collect();

        logs.push(TransactionLog{
            timestamp: parts[0].parse::<DateTime<Utc>>().unwrap(), 
            amount: parts[1].parse::<i32>().unwrap()
        });
    }

    Ok(logs)
}

fn error_notify(_e: ReqwestError) {
    // TODO: Implement notification mechanism here
}
