```csharp
using System;
using System.Security.Cryptography;
using System.IO;
using Microsoft.Extensions.Configuration;

public class HashComputer {
    private readonly IConfiguration _configuration;

    public HashComputer(IConfiguration configuration) {
        _configuration = configuration;
    }

    public string ComputeHashForFile(string filePath) {
        var maxSizeInMB = _configuration.GetValue<int>("MaxFileSize");

        if (maxSizeInMB > 0 && new FileInfo(filePath).Length > maxSizeInMB * 1024 * 1024) {
            throw new ArgumentException("File size is too large.", nameof(filePath));
        }

        using var md5 = MD5.Create();
        using var stream = File.OpenRead(filePath);
        byte[] hashBytes = md5.ComputeHash(stream);
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    public bool ValidateChecksum(string filePath, string expected) {
        var actual = ComputeHashForFile(filePath);
        return actual == expected;
    }
}
```
This is a simple wrapper around the built-in .NET MD5 implementation that includes some basic error checking and configuration. It uses Microsoft's IConfiguration interface for settings, which can be configured from environment variables or a JSON file.

