// Assumes that public key is already loaded into a char* variable named pub_key_data
static bool validate(const char* response) {
    json_error_t error;
    json_t *root = json_loads(response, 0, &error);

    if(!json_is_object(root)) {
        json_decref(root);
        return false;
    }

    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");

    if(!json_is_string(access_token) || !json_is_integer(expires_in) || !json_is_string(token_type)) {
        json_decref(root);
        return false;
