public:
    std::unordered_map<std::string, AttackPattern> attackPatterns;  // key: name of the pattern

    std::mutex mtx;

    void addAttackPattern(const AttackPattern& ap) {
        std::lock_guard<std::mutex> lock(mtx);
        attackPatterns.insert({ap.name, ap});
    }

    void executeAttack() {
        std::vector<AttackPattern> availablePatterns;
        for (const auto& pair : attackPatterns) {
            const AttackPattern& pattern = pair.second;
            if (pattern.cooldownDuration <= 0) {
                availablePatterns.push_back(pattern);
            }
        }

        // Sort patterns by priority, then by cooldown time
        std::sort(availablePatterns.begin(), availablePatterns.end(), [](const AttackPattern& a, const AttackPattern& b) {
            if (a.priorityLevel != b.priorityLevel) return a.priorityLevel > b.priorityLevel;
            else return a.cooldownDuration < b.cooldownDuration;
        });

        // Select the pattern with highest priority and lowest cooldown time
        if (!availablePatterns.empty()) {
            const AttackPattern& selected = availablePatterns[0];

            std::thread([this, selected]() {
                std::cout << "Attacking with " << selected.name << ". Energy consumed: " << selected.energyCost << std::endl;

                std::lock_guard<std::mutex> lock(mtx);
                attackPatterns[selected.name].cooldownDuration = selected.executionTime;  // Update cooldown time
            }).detach();
