class FileChangeHandler(FileSystemEventHandler):
    def __init__(self, loop, directory):
        self.loop = loop
        self.directory = directory

    def on_created(self, event):
        if not event.is_directory:
            filename = os.path.join(self.directory, event.src_path)
            md5hash = hashlib.md5(open(filename,'rb').read()).hexdigest() 
            self.loop.call_soon_threadsafe(log.info, f'MD5 Hash of {filename} is: {md5hash}.')

class FileMonitorService:
    def __init__(self, loop, directory):
        self.observer = Observer()
        self.handler = FileChangeHandler(loop, directory)
        self.directory = directory

    async def start_monitoring(self):
        self.observer.schedule(self.handler, self.directory, recursive=True)
        self.observer.start()

    def stop_monitoring(self):
        self.observer.stop()
        self.observer.join()

class KickStartSystem:
