        self.loop = asyncio.get_event_loop()
        self.config_modifier = KickstartConfigModifier(secrets_manager, cache)
        self.file_monitor_service = FileMonitorService(self.loop, directory)

    def start(self):
        tasks = asyncio.gather(
            self.file_monitor_service.start_monitoring(),  # Monitor files asynchronously
            # Other tasks here...
        )

        try:
            self.loop.run_until_complete(tasks)
        finally:
            self.loop.close()

    def stop(self):
        self.file_monitor_service.stop_monitoring()  # Stop monitoring files
