```c
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int key;
    long offset_value;
    char status;
} record_t;

typedef struct dynamic_collection {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    record_t *records;
} dynamic_collection_t;

void dynamic_collection_init(dynamic_collection_t *dc) {
    dc->capacity = 1024; /* initial capacity */
    dc->count = 0;
    dc->records = malloc(sizeof(*dc->records) * dc->capacity);
    pthread_mutex_init(&dc->lock, NULL);
}

void dynamic_collection_add(dynamic_collection_t *dc, record_t r) {
    pthread_mutex_lock(&dc->lock);
    if (dc->count == dc->capacity) {
        /* expand capacity */
        dc->records = realloc(dc->records, sizeof(*dc->records) * 2*dc->capacity);
        dc->capacity = 2*dc->capacity;
    }
    dc->records[dc->count++] = r;
    pthread_mutex_unlock(&dc->lock);
}
```
In this skeleton, a `dynamic_collection` is used to hold the records in a thread-safe manner. The `record` struct represents one record, and each `record` contains an integer key, long offset value, and character status field. In order to manage multiple threads' accesses, a mutex lock is used around the critical sections of code.

