#include <forward_list>
#include <string>

void insertStringAfter(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
    auto prev = list.before_begin();
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == target) {
            list.insert_after(it, toInsert);
            return;
        }
        prev = it;
    }

    // If target was not found in the list
    list.insert_after(prev, toInsert);
}
``` 
This function assumes that `list` is non-empty and modifies it directly, which might be undesirable depending on your use case. To make it safer you could return a new forward_list instead of modifying the original one.
