['Here is a simple C program that reads a text file and prints the contents of each line in a comma-separated format, with the last field of each line being the average of the last two fields. It allocates memory dynamically for each line and frees it after use. The input text file should be processed line by line, and it handles lines with varying lengths.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Failed to open file.\n");
        return 1;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        int lastSpaceIndex = -1;
        int secondLastSpaceIndex = -1;

        for (int i = strlen(line) - 2; i >= 0; i--) {
            if (line[i] == ' ' && lastSpaceIndex == -1) {
                lastSpaceIndex = i;
            } else if (line[i] == ' ' && lastSpaceIndex != -1) {
                secondLastSpaceIndex = i;
                break;
            }
        }

        char *field1 = malloc(lastSpaceIndex + 1);
        strncpy(field1, line, lastSpaceIndex);
        field1[lastSpaceIndex] = '\0';

        int num1 = atoi(line + lastSpaceIndex + 1);
        int num2 = atoi(line + secondLastSpaceIndex + 1);

        printf("%s, %.2f\n", field1, (num1 + num2) / 2.0);

        free(field1);
    }

    fclose(file);
    if (line) {
        free(line);
    }

    return 0;
}
```
Please note that this code assumes the input file is a text file with lines ending in two space-separated numbers. If your file format is different, you might need to adjust the parsing logic accordingly. Also, please make sure to handle any possible errors, like failing to open the file or dynamically allocated memory being unavailable.
']

