```cpp
// Include necessary headers
#include <pistache/endpoint.h>
#include <librdkafka/rdkafkacpp.h>

using namespace Pistache;

class HelloHandler : public Http::Handler {
public:
    HTTP_PROXY_HANDLER(HelloHandler)

    void onRequest(const Http::Request& request, Http::ResponseWriter writer) override{
        // Process the request and generate a response

        RdKafka::Producer *producer = RdKafka::Producer::create("localhost");
        std::string topic_str = "test";
        std::string msg_str = "Hello, World!";
        RdKafka::ErrorCode err = producer->produce(topic_str,
                                                   0, // Partition (unused)
                                                   RdKafka::Producer::RK_MSG_COPY,
                                                   const_cast<char *>(msg_str.c_str()), 
                                                   msg_str.size(),
                                                   nullptr, 
                                                   0, // Message timestamp (unused)
                                                   0, // Per-message opaque value passed to delivery report callback (unused)
                                                   nullptr); // Message headers, if any
        producer->flush(5*1000 /* wait for shortest time possible */);

        if (err != RdKafka::ERR_NO_ERROR){
            std::cerr << "% produce failed: " << RdKafka::err2str(err) << std::endl;
        } else {
            std::cerr << "% produced message!" << std::endl;
        }

        // Send the response back to the client
        writer.send(Http::Code::Ok, "Hello from REST API server!\n");
    }
};

int main() {
    Net::Address addr(Net::Ipv4::any(), Net::Port(9080));

    auto opts = Http::Endpoint::options().threads(1);
    Http::Endpoint server(addr);
    server.init(opts);
    server.setHandler(Http::make_handler<HelloHandler>());
    server.serve();
}
```
