extern crate chrono;
use chrono::{DateTime, Utc};
use std::collections::VecDeque;
use std::time::Duration;

pub struct Transaction {
    pub timestamp: DateTime<Utc>,
    pub amount: f64,
    pub id: String,
}

struct MovingAverage {
    window_size: usize,
    transactions: VecDeque<Transaction>,
    sum: f64,
}

impl MovingAverage {
    fn new(window_size: usize) -> Self {
        Self {
            window_size,
            transactions: VecDeque::new(),
            sum: 0.0,
        }
    }

    fn add(&mut self, transaction: Transaction) {
        if self.transactions.len() == self.window_size {
            let removed = self.transactions.pop_front().unwrap();
            self.sum -= removed.amount;
        }
        self.transactions.push_back(transaction);
        self.sum += transaction.amount;
    }

    fn average(&self) -> f64 {
        if self.transactions.is_empty() { 0.0 } else { self.sum / self.transactions.len() as f64 }
    }
}

pub struct TransactionProcessor {
    moving_average: MovingAverage,
    last_update: DateTime<Utc>,
}

impl TransactionProcessor {
    fn new(window_size: usize) -> Self {
        Self {
            moving_average: MovingAverage::new(window_size),
            last_update: Utc::now(),
        }
    }

    fn add(&mut self, transaction: Transaction) {
        if transaction.timestamp >= self.last_update + Duration::from_secs(60) {
            println_log_average();
            self.moving_average = MovingAverage::new(15);
            self.last_update = Utc::now();
        }

        self.moving_average.add(transaction);
    }

    fn print_log_average(&self) {
        println_log_average(&self.moving_average);
    }
}
```

This program creates a `Transaction` struct to hold transaction data and a `MovingAverage` struct to calculate the moving average of transactions over time. The `TransactionProcessor` struct integrates these components, continuously updating the moving average every minute. Please replace dummy implementations with actual ones (like API integration or logging).
