using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Configuration;
using Microsoft.WindowsAzure.Storage;
using Microsoft.WindowsAzure.Storage.Blob;
using Azure.Storage.Blobs;

public class FileTransferService : IFileTransferService
{
    private readonly CloudBlobClient blobClient;
    private readonly string containerName;

    public FileTransferService(IConfiguration configuration)
    {
        var connectionString = configuration["StorageConnectionString"];
        var storageAccount = CloudStorageAccount.Parse(connectionString);
        this.blobClient = storageAccount.CreateCloudBlobClient();
        this.containerName = configuration["ContainerName"];
    }

    public async Task<bool> TransferFileToBlobAsync(IFormFile file)
    {
        if (file == null || file.Length == 0) return false;

        var container = blobClient.GetContainerReference(containerName);

        // Adaptive chunking and memory management
        const int maxChunkSize = 4 * 1024 * 1024; // 4MB
        long filePosition = 0;
        byte[] buffer = new byte[maxChunkSize];

        while (filePosition < file.Length)
        {
            var chunkSize = Math.Min(maxChunkSize, file.Length - filePosition);

            using (var stream = new MemoryStream())
            {
                await file.CopyToAsync(stream);
                stream.Seek(filePosition, SeekOrigin.Begin);

                // Upload chunk to Azure Blob Storage
                var blobName = $"{Guid.NewGuid()}{Path.GetExtension(file.FileName)}";
                CloudBlockBlob blockBlob = container.GetBlockBlobReference(blobName);
                await blockBlob.UploadFromStreamAsync(stream);

                filePosition += chunkSize;
            }
        }

        return true;
    }
}
``` 
