public class EventService
{
    private static readonly ILogger Logger = LogManager.GetCurrentClassLogger();

    // A ConcurrentQueue is a thread-safe collection that you can use to add and remove items from multiple threads concurrently.
    private readonly BlockingCollection<string> _eventQueue; 

    public EventService()
    {
        _eventQueue = new BlockingCollection<string>();
    }

    // Start the service, this method should be called once in your application start up
    public void Start()
    {
        var cancellationTokenSource = new CancellationTokenSource();

        // Worker thread to handle events from queue
        var workerThread = new Thread(() => ProcessQueue(cancellationTokenSource.Token)); 
        workerThread.Start();
    }

    public void EnqueueEvent(string eventData)
    {
        _eventQueue.Add(eventData); // Add events to queue
    }

    private async Task ProcessQueue(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            string eventData = null;

            try
            {
                // Wait for an item to be available in the queue
                eventData = _eventQueue.Take(cancellationToken); 

                // Handle data persistence resiliently
                await Policy
                    .Handle<Exception>()
                    .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)))
                    .ExecuteAsync(async () =>
                    {
                        using (var scope = new TransactionScope(TransactionScopeOption.Required, 
                            new TransactionOptions { IsolationLevel = IsolationLevel.ReadCommitted }))
                        {
                            await PersistEventData(eventData); // Persist event data
                            scope.Complete();
                        }
                    });
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
                Logger.Info("Cancellation Requested");
                break;
            }
            catch (Exception ex)
            {
                Logger.Error(ex, $"Failed to process event: {eventData}");
            }
        }
    }

    private async Task PersistEventData(string eventData)
    {
        // Deserialize the event data into a dynamic object for schema evolution handling
        var deserializedEvent = JsonConvert.DeserializeObject<dynamic>(eventData);

        // Validate and migrate schema if needed
        await MigrateSchemaIfNeeded(deserializedEvent);

        // Save to database
        using (var dbContext = new MyDbContext())
        {
            dbContext.Events.Add((Event)deserializedEvent);
            await dbContext.SaveChangesAsync();
        }
    }

