int validateTokenResponse(const char* jsonStr) {
    json_object *jobj = json_tokener_parse(jsonStr);

    json_object *token, *expiresIn, *tokenType, *refreshToken;
    int isValid = 1; // Assume valid until proven otherwise

    if (!json_object_object_get_ex(jobj, "access_token", &token)) {
        isValid = 0;  // access_token not found
    } else if (!json_object_object_get_ex(jobj, "expires_in", &expiresIn) || json_object_get_int(expiresIn) <= 0) {
        isValid = 0;  // expires_in not found or less than/equal to zero
    } else if (!json_object_object_get_ex(jobj, "token_type", &tokenType) || strcmp(json_object_get_string(tokenType), "Bearer")) {
        isValid = 0;  // token_type not found or not 'Bearer'
    } else if (json_object_object_get_ex(jobj, "refresh_token", &refreshToken) && !strcmp(json_object_get_string(refreshToken), "")) {
        isValid = 0;  // refresh_token found but empty
    }

    json_object_put(jobj);

    return isValid;
}
