['Below is an example of how you might approach this task using Node.js, Express.js for server setup, child_process module for executing shell commands, Winston for logging and other libraries as per your requirement. It's a high level overview and does not contain actual implementation of all features mentioned above due to complexity but it provides a starting point for developing such service:

```javascript
const express = require('express');
const { exec } = require('child_process');
const winston = require('winston');
const rateLimit = require("express-rate-limit");

// Create logger with Winston
const logger = winston.createLogger({
  transports: [new winston.transports.Console()]
});

let whitelistCommands = [];

const app = express();
app.use(express.json());

// Rate limit configuration
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // Limit each IP to 100 requests per `window`
});
app.use(limiter);

// Update whitelist API endpoint
app.put('/commands', (req, res) => {
  whitelistCommands = req.body;
  logger.info('Updated whitelist: ', whitelistCommands);
  res.status(200).send({ success: true });
});

// Execute commands API endpoint
app.post('/commands', (req, res) => {
  const command = req.body;

  // Check if the command is whitelisted
  if (!whitelistCommands.includes(command)) {
    logger.error('Attempted to execute non-whitelisted command: ', command);
    return res.status(403).send({ error: 'Command not allowed.' });
  }

  // Execute shell command
  const process = exec(command, (error, stdout, stderr) => {
    if (error) {
      logger.error('Error executing command: ', command);
      return res.status(500).send({ error: 'Failed to execute command.' });
    }

    if (stderr) {
      logger.warn('Command produced stderr output: ', stderr);
    }

    logger.info('Command executed successfully with stdout: ', stdout);
    res.status(200).send({ success: true, output: stdout });
  });

  // Handle command timeout
  setTimeout(() => {
    process.kill();
    logger.warn('Command timed out: ', command);
    res.status(500).send({ error: 'Command execution timed out.' });
  }, 5000); // Set your own timeout limit here
});

app.listen(3000, () => {
  logger.info('Server is running on http://localhost:3000');
});
```
Remember to include error handling and logging as appropriate for production level code and it's highly recommended to have a robust security measure like authentication and authorization of requests. Testing should be done considering various edge cases such as security vulnerabilities, high load scenarios, etc.
