```python
from flask import Flask, request
import redis
import json

app = Flask(__name__)
redis_client = redis.Redis(host='localhost', port=6379)

@app.route('/vertex/<id>', methods=['POST', 'PUT'])
def add_update_vertex(id):
    data = request.get_json()

    # Enforce unique identifiers and constraints for vertices
    if redis_client.exists(f"v:{id}"):
        return {"error": "Vertex already exists"}, 409

    res = redis_client.set(f"v:{id}", json.dumps(data))

    if res:
        app.logger.info('Added/updated vertex %s', id)
        return {"success": True}, 201
    else:
        app.logger.error('Failed to add/update vertex %s', id)
        return {"error": "Operation failed"}, 500

@app.route('/vertex/<id>', methods=['DELETE'])
def delete_vertex(id):
    res = redis_client.delete(f"v:{id}")

    if res:
        app.logger.info('Deleted vertex %s', id)
        return {"success": True}, 200
    else:
        app.logger.error('Failed to delete vertex %s', id)
        return {"error": "Operation failed"}, 500

@app.route('/vertex/<id>', methods=['GET'])
def get_vertex(id):
    data = redis_client.get(f"v:{id}")

    if data is not None:
        app.logger.info('Retrieved vertex %s', id)
        return json.loads(data), 200
    else:
        app.logger.error('Vertex not found %s', id)
        return {"error": "Vertex not found"}, 404
```
