class DynamicRandomValueGenerator {
private:
    std::mt19937 gen; // Mersenne Twister random number generator
    std::uniform_real_distribution<double> distReal;
    std::uniform_int_distribution<int> distInt;
    std::mutex mtx; // Mutex for thread-safety
public:
    DynamicRandomValueGenerator() {
        std::random_device rd;  // Random seed from hardware
        gen = std::mt19937(rd());
        distReal = std::uniform_real_distribution<double>(0, 1);
        distInt = std::uniform_int_distribution<int>(0, 1);
    }

    double getRandomDouble() {
        std::lock_guard<std::mutex> lock(mtx); // Lock for thread safety
        return distReal(gen);
    }

    int getRandomInt() {
        std::lock_guard<std::mutex> lock(mtx);  // Lock for thread safety
        return distInt(gen);
    }
};
```
