void addConnection(NetworkConnectionStatus conn) {
    pthread_mutex_lock(&lock);
    if (connectionCount < MAX_CONNECTIONS) {
        connections[connectionCount++] = conn;
    } else {
        printf("Error: Maximum connection limit reached.\n");
    }
    pthread_mutex_unlock(&lock);
}

void removeConnection(int id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < connectionCount; ++i) {
        if (connections[i].connectionID == id) {
            connections[i] = connections[--connectionCount]; // Swap last element to the removed position.
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}
```
