class AttackManager {
private:
    std::vector<GameCharacter> characters;
    ExternalAPI api;
    std::atomic<bool> running{false};
    std::thread thread;
    std::mutex mtx;
    std::condition_variable cv;
    int currentAttack = 0;

public:
    AttackManager(std::vector<GameCharacter>& chars) : characters(chars) {}

    void start() {
        running = true;
        thread = std::thread(&AttackManager::run, this);
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mtx);
            running = false;
        }
        cv.notify_all();
        if (thread.joinable()) thread.join();
    }

private:
    void run() {
        while (running) {
            std::unique_lock<std::mutex> lock(mtx);

            // exponential backoff strategy
            for (int i = 0; running && i < 10; ++i) {
                if (cv.wait_for(lock, std::chrono::seconds(api.getCooldown() * (i+1)), [this]{ return !running; })) break; 
            }

            if (!running) break;

            // perform attack
            for (auto& character : characters) {
                character.performAttack(currentAttack);
            }

            currentAttack = (currentAttack + 1) % 3; // replace with actual sequence of attacks
        }
    }
};
