    private final DatabaseService databaseService;

    public DynamicDataProcessor(ExchangeService exchangeService, DatabaseService databaseService) {
        this.exchangeService = exchangeService;
        this.databaseService = databaseService;
    }

    @EventListener(ApplicationReadyEvent.class)
    public void runAfterStartup() {
        Flux<Data> dataStream = exchangeService.getHighVelocityDataStream();

        // Process and cache market indicators
        dataStream
            .filter(data -> /* some filter logic */)
            .transform(/* caching transformation */)
            .subscribe();

        // Save data to database
        dataStream
            .doOnNext(databaseService::saveData)
            .retry()
            .subscribe();
    }

    public static void main(String[] args) {
        SpringApplication.run(DynamicDataProcessor.class, args);
    }
}
```
