using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

public class ComponentUpdateService
{
    private readonly ILogger<ComponentUpdateService> _logger;
    private readonly HttpClient _httpClient;
    // Assuming the presence of ConnectionPool, CacheService and MessageBroker classes
    private readonly ConnectionPool _connectionPool;
    private readonly CacheService _cacheService;
    private readonly MessageBroker _messageBroker;

    public ComponentUpdateService(ILogger<ComponentUpdateService> logger, HttpClient httpClient, 
        ConnectionPool connectionPool, CacheService cacheService, MessageBroker messageBroker)
    {
        _logger = logger;
        _httpClient = httpClient;
        _connectionPool = connectionPool;
        _cacheService = cacheService;
        _messageBroker = messageBroker;
    }

    public async Task<bool> UpdateComponentAsync(string userId, string sessionToken, 
        string componentId, object updatedData)
    {
        try
        {
            // Validate the token with OAuth2 server. Replace with actual implementation.
            var isValid = await _httpClient.GetAsync($"/validate?token={sessionToken}");

            if (!isValid.IsSuccessStatusCode)
                throw new Exception("Invalid session token");

            // Use connection pool to get a database connection asynchronously. 
            using (var dbConnection = await _connectionPool.GetConnectionAsync())
            {
                var sqlCommand = $"UPDATE components SET data='{JsonConvert.SerializeObject(updatedData)}'" +
                                  $"WHERE userId='{userId}' AND componentId='{componentId}'";

                // Execute update query and log metrics.
                _logger.LogInformation("Executing SQL command: {sqlCommand}", sqlCommand);
                var result = await dbConnection.ExecuteAsync(sqlCommand);

                if (result == 0) 
                    throw new Exception("No matching components found");
            }

            // Update cache service with the updated data payload asynchronously
            await _cacheService.UpdateComponentCacheAsync(componentId, updatedData);

            // Notify subscribers of changes via message broker
            await _messageBroker.PublishMessageAsync(userId, componentId, updatedData);

            return true;
        }
        catch (Exception e)
        {
            _logger.LogError(e, "Failed to update component");
            throw;
        }
    }
}
```
This code uses the async/await pattern extensively for efficient handling of IO-bound operations like network calls and database queries. It also handles error scenarios robustly by throwing exceptions on failure and logging detailed information for troubleshooting. 

Please replace `ConnectionPool`, `CacheService` and `MessageBroker` classes with the actual implementations in your project. Similarly, update SQL command string according to your requirements as it's just a placeholder right now.
