#include <pthread.h>
#include <stdio.h>
#include <errno.h>

typedef struct record {
    int key;
    long offset;
    char status;
} record_t;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *worker(void *arg) {
    for (int i = 0; i < 10; ++i) {
        if ((errno = pthread_mutex_lock(&lock)) != 0) {
            perror("Failed to lock mutex");
            return NULL;
        }

        // Do work here...

        if ((errno = pthread_mutex_unlock(&lock)) != 0) {
            perror("Failed to unlock mutex");
            return NULL;
        }
    }

    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    if ((errno = pthread_create(&thread1, NULL, worker, NULL)) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    if ((errno = pthread_create(&thread2, NULL, worker, NULL)) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    if ((errno = pthread_join(thread1, NULL)) != 0) {
        perror("Failed to join thread");
        return 1;
    }

    if ((errno = pthread_join(thread2, NULL)) != 0) {
        perror("Failed to join thread");
        return 1;
    }

    return 0;
}
```
This is a simple example where two threads are created and perform some work protected by the same mutex. The `pthread_mutex_lock` function will block if another thread holds the lock, allowing us to ensure mutual exclusion and synchronization between threads. 

