    cache: HashMap<String, Arc<(Mutex<Vec<u8>>, DateTime<Utc>)>>,
}

impl Default for HttpCache {
    fn default() -> Self {
        Self {
            cache: HashMap::new(),
        }
    }
}

pub struct ServiceClient {
    http_client: HttpClient,
    config: Config,
    cache: Arc<Mutex<HttpCache>>,
}

impl ServiceClient {
    pub fn new(config: Config) -> Self {
        let client = reqwest::Client::builder().build().unwrap();

        Self {
            http_client: client,
            config,
            cache: Arc::new(Mutex::new(HttpCache::default())),
        }
    }

    pub async fn get(&self, url: &str) -> Result<Vec<u8>, reqwest::Error> {
        let cache = self.cache.lock().unwrap();

        if let Some((data, last_updated)) = cache.cache.get(url) {
            if self.config.should_retry(last_updated) {
                return Ok(*data.0.lock().unwrap());
            }
        }

        // Retry logic here...

        let res = self.http_client.get(url).send().await?;
        let bytes = res.bytes().await?;

        cache.cache.insert(url.to_string(), Arc::new((Mutex::new(bytes), now())));

        Ok(bytes)
    }
}
```
