use std::fmt;

fn append_slash_if_within_limit(s: &str, limit: usize) -> Result<String, fmt::Error> {
    if s.len() >= limit {
        return Ok(s.to_string());
    } else {
        let mut res = String::from(s);
        res.push('/');
        return Ok(res);
    }
}
```

