    }

    public T Load<T>(string key, T defaultValue) where T : new()
    {
        // Try to load from vault.
        try
        {
            var configSection = _configuration.GetSection(key);
            if (configSection != null && configSection.Exists())
                return configSection.Get<T>();
        }
        catch (Exception ex) when (!ex is ConfigurationException)
        {
            // Log vault load error, but continue with next fallback.
