#include <pthread.h>
typedef struct {
    int connectionID;
    time_t lastActiveTimestamp;
    bool activeStatus;
} NetworkConnectionStatus;

// Define a vector to hold connections
static std::vector<NetworkConnectionStatus> networkConnections;

// Lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addConnection(int connectionID, time_t lastActiveTimestamp, bool activeStatus) {
    pthread_mutex_lock(&lock);
    // Add a new connection with given parameters to the vector
    networkConnections.push_back({connectionID, lastActiveTimestamp, activeStatus});
    pthread_mutex_unlock(&lock);
}

void removeConnection(int connectionID) {
    pthread_mutex_lock(&lock);
    // Remove a connection with the given ID from the vector
    networkConnections.erase(std::remove_if(networkConnections.begin(), networkConnections.end(), [&](NetworkConnectionStatus ncs){return ncs.connectionID == connectionID;}), networkConnections.end());
    pthread_mutex_unlock(&lock);
}
