```c
#include <stdlib.h>

typedef struct {
    void* memory;
    size_t size;
} slab_t;

slab_t* allocate_slab(size_t size) {
    slab_t* slab = malloc(sizeof(slab_t));
    if (slab == NULL) return NULL;
    slab->memory = malloc(size);
    if (slab->memory == NULL) {
        free(slab);
        return NULL;
    }
    slab->size = size;
    return slab;
}

void* allocate_from_slab(slab_t* slab, size_t size) {
    if (slab == NULL || slab->memory + slab->size - size < slab->memory) return NULL;
    void* allocation = slab->memory;
    slab->memory += size;
    slab->size -= size;
    return allocation;
}
```
