#include <yaml-cpp/yaml.h>
#include <string>
#include <fstream>
#include <iostream>
#include <map>

class ConfigManager {
public:
    // Singleton pattern to ensure only one instance of the class exists
    static ConfigManager& getInstance() {
        static ConfigManager instance; 
        return instance;
    }

    void loadFromYaml(const std::string& filePath) {
        try {
            YAML::Node config = YAML::LoadFile(filePath);

            if (config["settings"]) {
                for (auto setting : config["settings"]) {
                    std::string key = setting.first.as<std::string>();
                    std::string value = setting.second.as<std::string>();

                    this->configuration[key] = value;
                }
            } else {
                throw std::runtime_error("Invalid configuration file format");
            }
        } catch (const YAML::Exception& e) {
            std::cerr << "Error loading config from YAML: " << e.what() << "\n";
        }
    }

    std::string getSetting(const std::string& key) const {
        if (this->configuration.count(key)) {
            return this->configuration.at(key);
        } else {
            throw std::runtime_error("Key not found in configuration");
        }
    }
private:
    ConfigManager() {} // Private constructor to prevent instantiation from outside the class
    std::map<std::string, std::string> configuration;
};
``` 

