    public class RealtimeDataSimulator
    {
        private readonly ProducerConfig _producerConfig;
        private readonly ISimulatedDataModel _dataModel;

        public RealtimeDataSimulator(ProducerConfig producerConfig, ISimulatedDataModel dataModel)
        {
            _producerConfig = producerConfig;
            _dataModel = dataModel;
        }

        public void Start()
        {
            var contextCancellationTokenSource = new CancellationTokenSource();

            // Use Polly to implement resilience patterns
            var retryPolicy = Policy.Handle<Exception>().RetryForeverAsync(_ => Task.Delay(TimeSpan.FromSeconds(5)));

            while (!contextCancellationTokenSource.IsCancellationRequested)
            {
                try
                {
                    using (var producer = new ProducerBuilder<Null, string>(_producerConfig).Build())
                    {
                        var data = _dataModel.Generate();

                        retryPolicy.Execute(() =>
                        {
                            return producer.ProduceAsync("topic", 
                                new Message<Null, string>() { Value = JsonConvert.SerializeObject(data) });
                        });
                    }
                }
                catch (Exception e)
                {
                    // Handle exceptions here...
                }
            }
        }
    }
}
