```python
from flask import Flask, request, jsonify
import requests
import time
from cachetools import LRUCache
app = Flask(__name__)
cache = LRUCache(maxsize=1024)

def get_coordinates_with_fallback(*args):
    for service in args:
        try:
            response = requests.get(service)
            if response.status_code == 200:
                return response.json()  # Assuming API returns JSON object with lat, long data
        except Exception as e:
            app.logger.error(f"Error connecting to {service}: {str(e)}")
    raise RuntimeError("Couldn't fetch coordinates.")

@app.route('/coordinates', methods=['GET'])
def get_coordinates():
    ip = request.args.get('ip')
    cached_result = cache.get(ip)
    if cached_result:
        lat, long, expiration_time = cached_result
        if time.time() < expiration_time:
            return jsonify({'lat': lat, 'long': long})
    api1 = f"http://api1/{ip}"  # replace with actual URLs of geolocation services
    api2 = f"http://api2/{ip}"
    try:
        data = get_coordinates_with_fallback(api1, api2)
    except Exception as e:
        return jsonify({'error': str(e)})
    lat, long = data['lat'], data['long']  # assuming API returns lat/long in this format
    cache[ip] = (lat, long, time.time() + 60)  # cache for a minute
    return jsonify({'lat': lat, 'long': long})
```

