["Below is an example code implementation for a basic modular, extensible logging framework using Python's `logging` module along with a plugin system to support multiple loggers and output formats. The configuration can be updated at runtime through environment variables or files:

```python
import os
from abc import ABCMeta, abstractmethod

class BaseLogger(metaclass=ABCMeta):
    @abstractmethod
    def log(self, message):
        pass

class ConsoleLogger(BaseLogger):
    def log(self, message):
        print(message)

class FileLogger(BaseLogger):
    def __init__(self, file_path):
        self.file_path = file_path

    def log(self, message):
        with open(self.file_path, 'a') as f:
            f.write(message + '\n')

class LoggerManager:
    LOGGERS = {
        'console': ConsoleLogger,
        'file': FileLogger,
    }

    def __init__(self):
        self._loggers = {}

    @classmethod
    def register_logger(cls, name, logger):
        cls.LOGGERS[name] = logger

    def get_logger(self, name):
        if name not in self._loggers:
            self._loggers[name] = self.LOGGERS[name]()
        return self._loggers[name]

class Configuration:
    def __init__(self):
        self._config = {}

    def load_from_env(self):
        for k, v in os.environ.items():
            if k.startswith('LOGGER_'):
                self._config[k] = v

    def load_from_file(self, file_path):
        with open(file_path, 'r') as f:
            for line in f:
                key, value = line.strip().split('=', 1)
                self._config[key] = value

    def get(self, key):
        return self._config.get(key)
```
To use this framework, you can do the following:

```python
manager = LoggerManager()
console_logger = manager.get_logger('console')
console_logger.log('Hello world to console')

