    if len(input) <= sizeLimit:
        input += '/'
        tempBuffer = input
    else:
        raise HTTPException(status_code=400, detail="Input string exceeded size limit")

    # Fetch UE and RNTI information
    ue_info = fetch_ue_information(N)
    rnti = fetch_rnti()

    if not ue_info or not rnti:
        raise HTTPException(status_code=500, detail="Error fetching system dependencies")

    # Check the cache first
    cached_result = cache.get('crc_indications')
    if cached_result:
        return Response(content=cached_result)

    # Process data and store in temp buffer
    pdu_list = []
    for i in range(N):
        pdu = {'RX_UE_INFORMATION_TAG': ue_info, 'RNTI': rnti, 'CRC_INDICATION_REL8_TAG': {'CRCFLAG': random.randint(0, 1)}}
        pdu_list.append(pdu)

    tempBuffer = pdu_list

    # Cache the result for future use
    cache.set('crc_indications', str(tempBuffer))

    return Response(content=str(tempBuffer))

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8000)
