// Service for managing video processing jobs
public class VideoProcessingService {
    private final StorageProvider storageProvider;
    private final TranscodingEngine transcodingEngine;

    // Inject dependencies
    public VideoProcessingService(StorageProvider storageProvider, TranscodingEngine transcodingEngine) {
        this.storageProvider = storageProvider;
        this.transcodingEngine = transcodingEngine;
    }

    public void processVideoJob(VideoJob videoJob) {
        // Retrieve video file from storage provider
        VideoFile videoFile = storageProvider.retrieveFile(videoJob);

        // Transcode the video file
        VideoFile transcodedVideoFile = transcodingEngine.transcode(videoFile, videoJob.getCodec());

        // Store the transocded video back into the storage provider
        storageProvider.storeFile(transcodedVideoFile, videoJob);
    }
}

// Interface for a storage provider like AWS S3, Google Cloud Storage or Azure Blob Storage
