```csharp
public class Chunker
{
    private int chunkSize; // based on real-time monitoring data

    public IEnumerable<byte[]> Chunkify(byte[] fileContent)
    {
        var chunks = new List<byte[]>();

        for (int i = 0; i < fileContent.Length; i += chunkSize)
        {
            int remainingBytes = fileContent.Length - i;
            int currentChunkSize = Math.Min(chunkSize, remainingBytes);

            var buffer = new byte[currentChunkSize];
            Array.Copy(fileContent, i, buffer, 0, currentChunkSize);
            chunks.Add(buffer);
        }

        return chunks;
    }

