    private readonly IRemoteStorageApi _remoteStorageApi;
    private readonly ILogger _logger;

    public FileIntegrityService(IRemoteStorageApi remoteStorageApi, ILogger logger)
    {
        _remoteStorageApi = remoteStorageApi;
        _logger = logger;
    }

    public async Task SynchronizeFileAsync(string fileId)
    {
        try
        {
            var fileMetadata = await FetchFileMetadataAsync(fileId);

            using (var md5 = MD5.Create())
            using (var stream = File.OpenRead(fileMetadata.LocalPath))
            {
                byte[] hashBytes = md5.ComputeHash(stream);
                var computedHash = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

                if (!computedHash.Equals(fileMetadata.MD5, StringComparison.OrdinalIgnoreCase))
                {
                    throw new Exception($"Computed hash '{computedHash}' does not match stored hash '{fileMetadata.MD5}'.");
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to synchronize file with ID: {fileId}");

            // retry logic would go here
            throw;
        }
    }

    private async Task<FileMetadata> FetchFileMetadataAsync(string fileId)
    {
        try
