**Python:**
```python
import hashlib
import os

def calculate_md5(file_path):
    # Check if the file exists
    if not os.path.isfile(file_path):
        print("File does not exist")
        return None

    md5 = hashlib.md5()  # Create a new MD5 hash object

    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(8192)  # Read file in chunks
            if not chunk:
                break
            md5.update(chunk)  # Update the hash object with the chunk

    return md5.hexdigest()  # Return the hexadecimal digest of the MD5 hash
```
