['Here is an example of how you could structure this task in Python using libraries such as `boto3` for AWS S3, `botocore` for error handling, and `configparser` for config management. This example does not cover everything you asked, but it should provide a starting point for your logging infrastructure:

```python
import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError
import configparser
import hashlib
import json
import os
import queue
import random
import threading
import time

# Load configuration
config = configparser.ConfigParser()
config.read('logging_config.ini')

LOGGING_CONFIGS = {
    'local': {'type': 'local', 'path': config['LOCAL']['Path']},
    's3': {'type': 's3', 'bucket': config['AWS']['Bucket'], 'region': config['AWS']['Region']},
    'cloudwatch': {'type': 'cloudwatch', 'log_group': config['CLOUDWATCH']['LogGroup'], 'stream': config['CLOUDWATCH']['Stream']}
}

# Set up queues and locks for thread safety
LOG_QUEUE = queue.Queue()
LOCK = threading.Lock()

class Logger:
    def __init__(self, log_configs):
        self.log_configs = log_configs
        self.checksums = {}

    def log(self, message):
        # Calculate checksum for data integrity
        LOCK.acquire()
        try:
            message_hash = hashlib.md5(message.encode()).hexdigest()
            self.checksums[message_hash] = message
        finally:
            LOCK.release()

        LOG_QUEUE.put((message, self.log_configs))

    def verify_integrity(self):
        for checksum in list(self.checksums.keys()):
            if random.randint(1, 10) == 5: # Simulate a failure
                raise ValueError('Data integrity check failed')

class LogHandler(threading.Thread):
    def __init__(self, message, log_configs):
        threading.Thread.__init__(self)
        self.message = message
        self.log_configs = log_configs

    def run(self):
        for config in self.log_configs:
            if config['type'] == 'local':
                with open(os.path.join(config['path'], f"{time.strftime('%Y%m%d-%H%M%S')}.log"), 'a') as logfile:
                    logfile.write(self.message)
            elif config['type'] == 's3':
                s3 = boto3.client('s3', region_name=config['region'])
                try:
                    s3.put_object(Body=self.message, Bucket=config['bucket'], Key=f"{time.strftime('%Y%m%d-%H%M%S')}.log")
                except (NoCredentialsError, PartialCredentialsError):
                    raise ValueError('AWS credentials not available') from None
            elif config['type'] == 'cloudwatch':
                pass # To be implemented with AWS SDK for CloudWatch Logs

def start_logging():
    while True:
        message, log_configs = LOG_QUEUE.get()
        handler = LogHandler(message, log_configs)
        handler.start()

if __name__ == '__main__':
    logger = Logger(LOGGING_CONFIGS.values())

    # Start logging worker threads
    for _ in range(int(config['GENERAL']['WorkerThreadCount'])):
        threading.Thread(target=start_logging).start()

    # Simulate high throughput
    for i in range(10**6):
        logger.log(json.dumps({'message': f"Log message {i}"}) + '\n')

    logger.verify_integrity()
```
This is a simplified example and does not cover all your requirements, but it should provide you with a good starting point for developing a robust logging infrastructure in Python. Please note that to achieve high throughput, you would need to use an asynchronous framework like `asyncio` or `gevent` depending on the specific needs of your application. For more complex cases and production environments, consider using established logging frameworks such as the ELK Stack (Elasticsearch, Logstash, Kibana) or Splunk with dedicated logging libraries.
']

