public class MessageController {

    private final WebSocketHandler webSocketHandler; 
    private final KafkaProducer kafkaProducer; 
    private final RedisCache redisCache; 

    public MessageController(WebSocketHandler webSocketHandler, 
                             KafkaProducer kafkaProducer, 
                             RedisCache redisCache) {
        this.webSocketHandler = webSocketHandler;
        this.kafkaProducer = kafkaProducer;
        this.redisCache = redisCache;
    }

    @PostMapping("/sendMessage")
    public ResponseEntity<String> sendMessage(@RequestBody Message message) {
        // Send the message to Kafka, which will be processed asynchronously 
        kafkaProducer.send(message);

        // Send the message through WebSocket if possible
        webSocketHandler.handle(message);

        // Store session in Redis for fast access 
        redisCache.putSession(message.getSessionId(), message.getUser());

        return ResponseEntity.ok("Message sent");
    }
}
```

