pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile;
const char* logFileName = "/tool.log"; 
char configDir[PATH_MAX];
int largest = 0;

void* processInput(void *arg) {
    int num, ret;

    while((ret = scanf("%d", &num)) != EOF) {
        if (ret == 1){
            pthread_mutex_lock(&mtx);
            largest = num > largest ? num : largest; 
            fprintf(logFile, "Successfully processed number: %d\n", num);
            pthread_mutex_unlock(&mtx);
        } else {
            fprintf(stderr, "Invalid input detected. Please enter only integers.\n");
            exit(1);
        }
    }
    return NULL;
}

void handleDir() {
    struct stat st = {0};

    if (stat(configDir, &st) == -1) {
        mkdir(configDir, 0755); // create directory with necessary permissions
        fprintf(logFile, "Directory created: %s\n", configDir);
    } else {
        fprintf(logFile, "Using existing directory: %s\n", configDir);
    }
}

void handleEnv() {
    if (setenv("CONFIG_DIR", configDir, 1) != 0){ // set environment variable
        perror("Error setting CONFIG_DIR");
        fprintf(logFile, "Failed to set CONFIG_DIR: %s\n", strerror(errno));
    } else {
        fprintf(logFile, "CONFIG_DIR successfully set\n");
    }
}

int main(int argc, char *argv[]) {

    assert(argc == 2);  // program expects a single command line argument for config directory name

    snprintf(configDir, sizeof(configDir), "%s/%s", getenv("PWD"), argv[1]); // create absolute path to configuration directory
    logFile = fopen((const char*)logFileName, "w");  // open log file for writing

    pthread_t thread;
    if(pthread_create(&thread, NULL, processInput, NULL)){
        perror("Thread creation failed");
        exit(-1);
    }
    handleDir();
    handleEnv();

    if (pthread_join(thread, NULL)) { // wait for thread to finish before exiting main
        perror("Join failed\n");
        exit(-2);
    }

    printf("Largest number: %d\n", largest); 

    fclose(logFile); // close log file

    return 0;
}
