class EventDrivenFramework:
    def __init__(self):
        self.subscriptions = {}

    def subscribe(self, event_type: str, callback):
        if event_type not in self.subscriptions:
            self.subscriptions[event_type] = []
        self.subscriptions[event_type].append(callback)

    def publish(self, event_type: str, data=None):
        if event_type in self.subscriptions:
            for callback in self.subscriptions[event_type]:
                callback(data)

class MessageBroker:
    def __init__(self):
        self.framework = EventDrivenFramework()

    def publish_message(self, topic, message):
        # Publish the message to the specified topic
        pass

    def subscribe_to_topic(self, topic, callback):
        self.framework.subscribe(topic, callback)
``` 
