1) Define the basic structure for your cache which includes methods for setting, getting, deleting data and handling expiration times.

```python
import time

class CacheItem(object):
    def __init__(self, key, value, expire_time=None):
        self.key = key
        self.value = value
        if expire_time is None:
            self.expire_time = float('inf')  # never expires
        else:
            self.expire_time = time.time() + expire_time

class Cache(object):
    def __init__(self, capacity=1024):
        self._data = {}
        self.capacity = capacity

    def set(self, key, value, expire_time=None):
        if len(self._data) >= self.capacity:  # evict oldest item
            self.evict()
        self._data[key] = CacheItem(key, value, expire_time)

    def get(self, key):
        item = self._data.get(key)
        if item is not None and time.time() < item.expire_time:
            return item.value
        else:
            del self._data[key]  # remove expired or missing items
        return None
```
2) Handle external requests using an API wrapper with retry logic to handle transient errors, and securely manage API keys.

```python
import requests
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry

class APIClient:
    def __init__(self, base_url):
        self._base_url = base_url
        retry_strategy = Retry(total=3, backoff_factor=1)  # 3 retries with 1 second delay
        adapter = HTTPAdapter(max_retries=retry_strategy)
        self.session = requests.Session()
        self.session.mount("https://", adapter)

    def fetch_data(self, endpoint):
        response = self.session.get(f"{self._base_url}/{endpoint}")
        return response.json()  # assuming json response for simplicity
```
