```cpp
void StreamingMediaProcessor::setThreadPoolSize(size_t size) {
    std::lock_guard<std::mutex> lock(mtx);  // Protect concurrent access to the thread pool.
    while (threadPool.size() > size) {  // Reduce the number of threads if necessary.
        threadPool.back().join();
        threadPool.pop_back();
    }
    for (size_t i = threadPool.size(); i < size; ++i) {  // Add new threads to reach the desired pool size.
        threadPool.emplace_back([this]() { doWork(); });
    }
}
```
