['```csharp
using UnityEngine;
using System;

public class RandomNumberGenerator 
{
    private int minValue;
    private int maxValue;

    public RandomNumberGenerator(int min, int max)
    {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum value");

        this.minValue = min;
        this.maxValue = max;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(this.minValue, this.maxValue);
    }

    public int GetRandomInt()
    {
        // The second argument in the Range function is exclusive, so add 1 to include maxValue in the range
        return UnityEngine.Random.Range(this.minValue, this.maxValue + 1);
    }

    public override string ToString()
    {
        return $"Min Value: {this.minValue}, Max Value: {this.maxValue}";
    }
}
```

This class creates a random number generator that uses Unity's Random.Range function to generate numbers within a specified range. The constructor requires two integers, which define the minimum and maximum values for the generated numbers respectively. Two methods `GetRandomFloat` and `GetRandomInt` generate a random float or integer respectively within this range. The class overrides the ToString method to provide a human-readable representation of the object.
']

