```javascript
const pino = require('pino');
const logger = pino();

class DataTransferModule {
  constructor(chunks) {
    this._buffer = Buffer.concat(chunks);
  }

  copyData(startIndex, byteCount) {
    return new Promise((resolve, reject) => {
      try {
        if (startIndex < 0 || startIndex > this._buffer.length - 1 || 
            byteCount < 0 || typeof byteCount !== 'number') {
          throw new Error('Invalid inputs');
        }

        const endIndex = Math.min(this._buffer.length, startIndex + byteCount);
        const newBuffer = this._buffer.slice(startIndex, endIndex);

        resolve(newBuffer);
      } catch (err) {
        logger.error('An error occurred:', err);
        reject(err);
      }
    });
  }
}
```
