        this.api = new CloudStorageProviderAPI();
        // Initialize your API here with necessary credentials and configurations
    }

    public void upload(File file) {
        UploadTask task = new UploadTask(file);
        Future<?> future = executor.submit(task);
        activeTasks.put(task.getId(), future);
    }

    public void download(String id) {
        DownloadTask task = new DownloadTask(id);
        Future<?> future = executor.submit(task);
        activeTasks.put(task.getId(), future);
