use std::time::Duration;

struct CustomHttpClient {
    client: Client<HttpsConnector<HttpConnector>>,
}

impl CustomHttpClient {
    fn new() -> Self {
        let https = HttpsConnector::new(4, Some(SslConfig::default())).unwrap();
        let connector = HttpConnector::new(4);
        let client = Client::builder().build_untrusted(https, connector);

