    kafka_producer: futures_util::Sink<A>,
}

impl<R, A> AnalyticsService<R, A> {
    pub async fn new(redis_uri: &str, kafka_brokers: &[&str]) -> Result<Self, Box<dyn std::error::Error>> {
        let redis_client = R::Client::open(redis_uri).await?;
