import java.util.*;

public class RandomValueGenerator {
    private int min;
    private int max;

    public RandomValueGenerator(int min, int max) {
        this.min = min;
        this.max = max;
    }

    public float getRandomFloat() {
        return new Random().nextFloat() * (this.max - this.min) + this.min;
    }

    public int getRandomInt() {
        return new Random().nextInt((this.max - this.min) + 1) + this.min;
    }

    @Override
    public String toString() {
        return "Range is from: " + min + " to " + max;
    }
}
```

