    public async Task<FileIntegrityResult> ComputeAndSynchronize(string fileId) {
        // Get file metadata from cloud storage API
        var fileMetadata = await _cloudStorageApi.GetFileMetadata(fileId);

        // Decide which checksum algorithm to use based on user configuration or default settings
        var checksumAlgorithm = _checksumAlgorithmFactory.CreateChecksumAlgorithm(userConfiguration);

        // Compute the checksum for the file and encrypt it using a secure method (e.g. AES)
        var encryptedChecksum = await checksumAlgorithm.ComputeAndEncrypt(fileId);

        // Compare the computed checksum with the one stored in the cloud storage API 
        bool isValid = await _cloudStorageApi.VerifyFileIntegrity(fileId, encryptedChecksum);

        return new FileIntegrityResult {
