@RestController
public class MyController {

    @PostMapping("/process")
    public ResponseEntity<?> process(@RequestBody byte[] data) {
        try {
            Object obj = deserializeObject(data);
            // Handle the object as per requirement.
            return new ResponseEntity<>(HttpStatus.OK);
        } catch (Exception e) {
            return new ResponseEntity<>("Invalid Data", HttpStatus.BAD_REQUEST);
        }
    }

    private Object deserializeObject(byte[] data) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bis = new ByteArrayInputStream(data);
        ObjectInput in = null;
        try {
            in = new ObjectInputStream(bis);
            return in.readObject();
        } finally {
            try {
                if (in != null) {
                    in.close();
                }
            } catch (IOException ex) {
                // ignore close exception
            }
        }
    }
}
```
