// A function to execute tasks concurrently using threads
void runTasksConcurrently(std::vector<std::function<void()>>& tasks) {
    std::vector<std::thread> threadPool;

    for (auto& task : tasks) 
        threadPool.push_back(std::thread(task));

    for (auto& th : threadPool)
        if (th.joinable()) 
            th.join();
}

// A function to compute the MD5 hash of a string in C#
public static string ComputeMD5Hash(string input) {
    using (System.Security.Cryptography.MD5 md5 = System.Security.Cryptography.MD5.Create()) 
    {
        byte[] inputBytes = System.Text.Encoding.ASCII.GetBytes(input);
        byte[] hashBytes = md5.ComputeHash(inputBytes);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < hashBytes.Length; i++) 
            sb.Append(hashBytes[i].ToString("X2"));

        return sb.ToString();
    }
}
