```csharp
using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

public class HtmlContentService : IHtmlContentService {
    private readonly ConcurrentQueue<Task> _taskQueue = new ConcurrentQueue<Task>();

    // Assume this is a dependency to handle CDN operations. 
    private readonly ICdnHandler cdnHandler;

    public HtmlContentService(ICdnHandler cdnHandler) {
        this.cdnHandler = cdnHandler;
    }

    public async Task UpdateAsync(PageSection pageSection, string elementId, string htmlContent) {
        var task = new Task(async () => {
            try {
                await cdnHandler.UpdateContentAsync(pageSection, elementId, htmlContent);
            } catch (Exception ex) {
                // Log and handle exceptions here
                Console.WriteLine($"Error updating content: {ex}");
            }
        });

        _taskQueue.Enqueue(task);

        if (_taskQueue.Count >= Constants.MaxConcurrentRequests) {
            await Task.WhenAny(_taskQueue, Task.Delay(Constants.TaskExecutionTimeout));
            _taskQueue.TryDequeue(out var completedTask);
            // If the task is not completed, add it back to the queue for retry
            if (!completedTask.IsCompleted) {
                _taskQueue.Enqueue(completedTask);
            }
        } else {
            await Task.Delay(Constants.IdleTimeBeforeExecution);
        }
    }
}
```
This is a very simplified version of your service, you would need to add a lot more code to handle different CDNs, logging and error handling, queuing mechanism, rate limiting strategies etc. Also, I have made assumptions about `ICdnHandler` interface, `PageSection` class, constants for configuration, and didn't include any form of monitoring or logging system which would need to be implemented as well.

