pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Connection connections[MAX_CONNECTIONS];
int connectionCount = 0;

void addConnection(char* id, enum ProtocolType protocolType) {
    pthread_mutex_lock(&lock);

    if (connectionCount >= MAX_CONNECTIONS) {
        printf("Maximum connections reached. Cannot add new one.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Connection connection = {id, time(NULL), protocolType, 1};
    connections[connectionCount] = connection;
    connectionCount++;

    pthread_mutex_unlock(&lock);
}

void removeConnection(char* id) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < connectionCount; i++) {
        if (strcmp(connections[i].id, id) == 0) {
            connections[i] = connections[connectionCount-1];
            connectionCount--;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

