```csharp
using System;
using System.IO;
using System.Collections.Concurrent;
using System.Threading;
using Microsoft.Extensions.Logging;

public class RandomValueGenerator 
{
    private static readonly object _lock = new();
    private readonly ConcurrentDictionary<string, double> _performanceMetrics = new();

    public int GetRandomInt(int min, int max)
    {
        lock (_lock)
        {
            var watch = System.Diagnostics.Stopwatch.StartNew();
            Random randNum = new Random();
            var value = randNum.Next(min, max);
            watch.Stop();

            _performanceMetrics["GetRandomInt"] += watch.ElapsedMilliseconds;
            return value;
        }
    }

    public double GetRandomDouble(double min, double max)
    {
        lock (_lock)
        {
            var watch = System.Diagnostics.Stopwatch.StartNew();
            Random randNum = new Random();
            var value = min + (max - min) * randNum.NextDouble();
            watch.Stop();

            _performanceMetrics["GetRandomDouble"] += watch.ElapsedMilliseconds;
            return value;
        }
    }
}

public class FileProcessor 
{
