```java
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import org.springframework.stereotype.Service;

import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;

@Service
public class PaymentGateway {
    private List<PaymentProcessor> paymentProcessors;
    private ThreadPoolTaskExecutor taskExecutor;

    @Autowired
    public PaymentGateway(List<PaymentProcessor> paymentProcessors, ThreadPoolTaskExecutor taskExecutor) {
        this.paymentProcessors = paymentProcessors;
        this.taskExecutor = taskExecutor;
    }

    public void processTransactionRequests(Map<String, String> transactionData) {
        List<CompletableFuture<Void>> futures = paymentProcessors.stream()
                .map(paymentProcessor -> CompletableFuture.supplyAsync(() -> paymentProcessor.processPayment(transactionData), taskExecutor))
                .collect(Collectors.toList());
        // Wait for all tasks to finish
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
    }
}
```

This is a simplified example of the system design. Implementing it involves many components such as `PaymentProcessor` interface, various implementations for each payment gateway (like `StripePaymentProcessor`), and others to handle transaction data securely, retry mechanism, etc. This code won't compile as is because of missing classes and configurations. 

