```csharp
using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Http;
using System;
using System.Linq;
using System.Security.Claims;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using Swashbuckle.AspNetCore.Annotations;
using Microsoft.AspNetCore.HttpOverrides;

[ApiController]
[Route("api/[controller]")]
public class ComponentStateController : ControllerBase
{
    private readonly IDistributedCache _cache;
    private readonly IAuthorizationService _authorizationService;
    private readonly ILogger<ComponentStateController> _logger;

    public ComponentStateController(IDistributedCache cache, 
                                    IAuthorizationService authorizationService, 
                                    ILogger<ComponentStateController> logger)
    {
        _cache = cache;
        _authorizationService = authorizationService;
        _logger = logger;
    }

    [HttpPost]
    [ProducesResponseType(StatusCodes.Status201Created)]
    [SwaggerOperation("Update Component State")]
    public async Task<IActionResult> UpdateComponentStateAsync([FromBody] JObject data)
    {
        var authResult = await _authorizationService.AuthorizeAsync(User, null, "OAuthPolicy");

        if (!authResult.Succeeded)
            return Forbid();

        var cacheKey = $"ComponentState:{GetClientId()}";
        var componentStates = await _cache.GetStringAsync(cacheKey);

        JObject states;

        if (componentStates == null)
            states = new JObject();
        else
            states = JObject.Parse(componentStates);

        foreach (var property in data.Properties())
            states[property.Name] = property.Value;

        await _cache.SetStringAsync(cacheKey, JsonSerializer.Serialize(states));

        return CreatedAtAction(nameof(GetComponentState), new { clientId = GetClientId() }, "Success");
    }

    [HttpGet("{clientId}")]
    public async Task<IActionResult> GetComponentState(string clientId)
    {
        var componentStates = await _cache.GetStringAsync($"ComponentState:{clientId}");

        if (componentStates == null)
            return NotFound();

        return Ok(JObject.Parse(componentStates));
    }

    private string GetClientId() 
    {
        var clientId = User?.Claims?.FirstOrDefault(c => c.Type == ClaimTypes.NameIdentifier)?.Value;

        if (string.IsNullOrEmpty(clientId))
            throw new InvalidOperationException("User is not authenticated");

        return clientId; 
    }
}
```
This code assumes that you have added OAuth2-compliant authentication server configuration and authorization policy named "OAuthPolicy". It also expects a Distributed Cache Service to be setup in your project, which can be done using Redis or SQL Server.

