import java.util.*;
import java.util.concurrent.*;

public class TaskQueue {
    private final BlockingQueue<Task> queue = new LinkedBlockingQueue<>();
    private ExecutorService executor;

    public void start() {
        int numThreads = 10; // Number of threads to handle tasks, adjust as needed.
        executor = Executors.newFixedThreadPool(numThreads);

        for (int i = 0; i < numThreads; i++) {
            Runnable taskHandler = () -> {
                try {
                    while (!Thread.currentThread().isInterrupted()) {
                        Task task = queue.take();
                        processTask(task);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            };

            executor.execute(taskHandler);
        }
    }

    public void stop() {
        executor.shutdownNow();
    }

    public void submitTask(Task task) {
        queue.add(task);
    }

    private void processTask(Task task) {
        // This is where your tasks get processed. 
        // Depending on the type of task, you'll probably want to switch this out for some actual logic.
        System.out.println("Processing " + task);
    }

    public static void main(String[] args) throws InterruptedException {
