['Here's an outline of how you might structure such a program in C. Please note that this is only a skeleton code snippet and does not include all the functionalities you specified above. It also assumes you have basic knowledge on how to use pthreads, json-c library for JSON manipulation, libpq-fe.h for PostgreSQL and securely handling environment variables:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <limits.h>
#include <sys/stat.h>
#include <pthread.h>
#include <json-c/json.h>
#include <libpq-fe.h>

// Mutex for thread safety
static pthread_mutex_t lock;

void *processInteger(void *arg) {
    int value = *((int *) arg);

    // Thread safe code to find the maximum integer
    pthread_mutex_lock(&lock);
    static int max = 0;
    if (value > max) 
        max = value;
    pthread_mutex_unlock(&lock);

    return NULL;
}

int main(int argc, char **argv) {
    // Check if command line argument is provided
    if (argc != 2) {
        printf("Usage: %s <directory>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Ensure directory exists and set environment variable
    struct stat st = {0};
    if (stat(argv[1], &st) == -1) {
        mkdir(argv[1], 0700);
    }
    setenv("CONFIG_DIR", argv[1], 1);

    // Initialize mutex
    pthread_mutex_init(&lock, NULL);

    // Dynamic list of integers from standard input
    int *integers = malloc(sizeof(int));
    int size = 0;
    int input;
    while (scanf("%d", &input) != EOF) {
        integers[size++] = input;
        integers = realloc(integers, sizeof(int) * (size + 1));
    }

    // Create threads for each integer in list and start processing
    pthread_t *threads = malloc(sizeof(pthread_t) * size);
    for (int i = 0; i < size; i++) {
        if (pthread_create(&threads[i], NULL, processInteger, &integers[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    // Join all threads and free resources
    for (int i = 0; i < size; i++) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return 2;
        }
    }

    pthread_mutex_destroy(&lock);
    free(integers);
    free(threads);

    // Save result to JSON file
    json_object *jobj = json_object_new_object();
    json_object_object_add(jobj, "max", json_object_new_int(processInteger(NULL)));
    FILE* fp = fopen("config.json", "w");
    fputs(json_object_to_json_string(jobj), fp);
    fclose(fp);

    return 0;
}
```
This program reads integers from standard input and creates a new thread for each integer to process it. It then uses a mutex to ensure that the maximum value is updated safely across threads. This code doesn't include all functionality you specified but it provides the structure on how you could build such an application in C.
']

