Let's consider using `boost::shared_mutex` and `std::unordered_map` to handle concurrent read/write operations. We use Boost for simplicity and it is widely used in many production systems, but you can replace it with other thread-safe data structures if necessary:

```cpp
#include <string>
#include <unordered_map>
#include <shared_mutex>
#include <boost/thread.hpp>

struct Entry {
    std::string key;
    double value;
};

class DynamicCollection {
public:
    bool add(const std::string& key, double value) {
        boost::upgrade_lock<boost::shared_mutex> lock(_access);
        auto it = _map.find(key);

        if (it != _map.end())
            return false;

        boost::upgrade_to_unique_lock<boost::shared_mutex> uniqueLock(lock);
        _map.insert({key, {key, value}});
        return true;
    }

    bool get(const std::string& key, Entry& entry) const {
        boost::shared_lock<boost::shared_mutex> lock(_access);
        auto it = _map.find(key);

        if (it == _map.end())
            return false;

        entry = it->second;
        return true;
    }

private:
    mutable boost::shared_mutex _access;
    std::unordered_map<std::string, Entry> _map;
};
```
