```java
import java.util.concurrent.*;

public class DistributedEventProcessingPipeline {
    private final BlockingQueue<Object> eventQueue;
    private final ExecutorService executorService;
    private final List<EventProcessor> eventProcessors;

    public DistributedEventProcessingPipeline() {
        int threadPoolSize = Runtime.getRuntime().availableProcessors();

        this.eventQueue = new LinkedBlockingQueue<>(50_000_000);  // Up to 50 million events in the queue
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
        this.eventProcessors = new ArrayList<>();
    }

    public void start() {
        for (EventProcessor eventProcessor : eventProcessors) {
            executorService.submit(() -> {
                while (!Thread.currentThread().isInterrupted()) {
                    try {
                        Object event = eventQueue.take();
                        eventProcessor.process(event);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            });
        }
    }

    public void stop() {
        executorService.shutdownNow();
    }

    public void submitEvent(Object event) {
        try {
            eventQueue.put(event);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
```

Each EventProcessor would be a different component that processes the events in its own way based on the type of the event. The routing strategy can be implemented as part of each EventProcessor or as a separate component, depending on your requirements and design choices. 

