1. `fileChunkHandler` module: 
```javascript
const fs = require('fs').promises;
const axios = require('axios');
const { Pool } = require('workerpool');
const workerPool = Pool();

let fileCount = 0;

function processFile(filePath, chunkSize) {
  return new Promise((resolve, reject) => {
    fs.open(filePath, 'r')
      .then(fd => getMetadataFromAPI(filePath))
      .then(({ checksum, timestamp }) => readAndProcessChunks(fd, chunkSize, checksum, timestamp))
      .catch(err => reject(`Error processing file: ${err}`));
  });
}

async function getMetadataFromAPI(filePath) {
  try {
    const response = await axios.get('apiUrl', { params: { filePath } }); // replace 'apiUrl' with actual API URL
    return response.data;
  } catch (err) {
    throw new Error(`Error fetching metadata from API: ${err}`);
  }
}

async function readAndProcessChunks(fd, chunkSize, checksum, timestamp) {
  let buffer = Buffer.alloc(chunkSize);
  fileCount++;
  workerPool.exec('processChunk', [buffer, checksum, timestamp])
    .then(() => {
      if (fileCount > 0) {
        fs.close(fd);
        fileCount--;
      }
      resolve();
    })
    .catch(err => reject(`Error processing chunks: ${err}`));
  });
}
```
