['Your request involves designing a complex system and implementing it would be quite extensive to show in this text-based platform. However, I can provide you with an outline of how you might approach this project using Python as the primary language for illustrative purposes. 

This is not a complete solution but should serve as a starting point:

```python
import threading
from concurrent.futures import ThreadPoolExecutor
import requests
import logging
import json
import time
import hashlib
import hmac
import base64

# Custom Exception Handling classes
class APIError(Exception): pass
class AuthenticationError(APIError): pass
class RateLimitExceeded(APIError): pass

class APIClient:
    def __init__(self, api_key, secret_key, endpoint, auth=None):
        self.api_key = api_key
        self.secret_key = secret_key
        self.endpoint = endpoint
        self.auth = auth or BasicAuth(api_key, secret_key)

    def get_resource(self, resource_id):
        url = f"{self.endpoint}/resources/{resource_id}"
        response = requests.get(url, auth=self.auth)
        if response.status_code == 401:
            raise AuthenticationError()
        elif response.status_code == 429:
            raise RateLimitExceeded()
        elif not response.ok:
            raise APIError(f"API call failed with status code {response.status_code}")
        return response.json()

class BasicAuth(requests.auth.AuthBase):
    def __init__(self, username, password):
        self.username = username
        self.password = password

    def __call__(self, r):
        encoded_credentials = base64.b64encode(f"{self.username}:{self.password}".encode()).decode()
        r.headers['Authorization'] = f'Basic {encoded_credentials}'
        return r

class APIThrottler:
    def __init__(self, limit):
        self._lock = threading.Lock()
        self._limit = limit
        self._count = 0

    def acquire(self):
        with self._lock:
            if self._count >= self._limit:
                raise RateLimitExceeded()
            self._count += 1

    def release(self):
        with self._lock:
            self._count -= 1

class API:
    def __init__(self, api_key, secret_key, endpoint):
        self.client = APIClient(api_key, secret_key, endpoint)
        self.throttler = APIThrottler(limit=10)  # Example limit

    def get_resource(self, resource_id):
        try:
            self.throttler.acquire()
            return self.client.get_resource(resource_id)
        finally:
            self.throttler.release()

class APIManager:
    def __init__(self, apis):
        self.apis = {api.__class__.__name__: api for api in apis}

    def get_resource(self, resource_id):
        # Here you could select the API based on request characteristics and system load
        return self.apis['API'].get_resource(resource_id)
``` 
This is a very basic example and does not cover all aspects of your request such as encryption protocols, JSON parser with lexer and parser for custom protocol grammar etc. Writing a complete solution in the text-based interface would be beyond the scope. I recommend working on this project locally using a proper IDE or development environment to fully benefit from code completion, debugging, version control, testing, etc.
']

['```rust
#[macro_use]
extern crate log;
extern crate futures;
extern crate hyper;
extern crate rocket;
extern crate serde;
extern crate serde_json;
extern crate jsonwebtoken as jwt;
extern crate oauth2 as oauth;
extern crate redis;
extern crate reqwest;

use hyper::rt::FutureStream;
use rocket::routes;
use std::sync::Arc;
use serde_json::Value as JsonValue;
use jwt::TokenData;
use oauth::{UrlAuthorization, Client};
use redis::Client as Redis;
use reqwest::Error as ReqwestError;

// Token storage and refresh strategies
#[derive(Debug)]
pub struct Tokens {
    access: String,
    refresh: Option<String>,
}

impl Tokens {
    pub fn new(access: &str, refresh: Option<&str>) -> Self {
        Self {
            access: access.to_string(),
            refresh: refresh.map(|r| r.to_string()),
        }
    }
}

// OAuth2 client configuration
struct OauthConfig {
    client_id: String,
    client_secret: String,
    redirect_uri: String,
}

impl OauthConfig {
    pub fn new(client_id: &str, client_secret: &str, redirect_uri: &str) -> Self {
        Self {
            client_id: client_id.to_string(),
            client_secret: client_secret.to_string(),
            redirect_uri: redirect_uri.to_string(),
        }
    }
}

// Redis client configuration
struct RedisConfig {
    address: String,
}

impl RedisConfig {
    pub fn new(address: &str) -> Self {
        Self {
            address: address.to_string(),
        }
    }
}

// Error handling and retrying logic for third-party API requests
async fn fetch_from_api<F, T>(fut: F) -> Result<T, ReqwestError> 
where 
    F: FutureStream + 'static,
    F::Item: Into<Result<T, ReqwestError>>,
{
    let mut backoff = std::time::Duration::from_secs(1);
    loop {
        match fut.await.into() {
            Ok(data) => return Ok(data),
            Err(err) => {
                errorln_enabled(|| format_args_warn(&format_args_err(&err, "Request failed")));
                tokio::time::sleep(backoff).await;
                backoff *= 2;
            }
        }
    }
}

// Data fetching and processing functions for external systems
async fn fetch_employee_details_from_api(client: &reqwest::Client, token: Option<&str>) -> Result<JsonValue, ReqwestError> {
    let url = "http://external-system.com/api/employees";
    let fut = client.get(url).bearer_auth(token.unwrap_or("")).send();
    fetch_from_api(fut).await
}

async fn fetch_data_from_third_party_api(client: &reqwest::Client, token: Option<&str>) -> Result<JsonValue, ReqwestError> {
    let url = "http://third-party.com/api";
    let fut = client.get(url).bearer_auth(token.unwrap_or("")).send();
    fetch_from_api(fut).await
}

async fn fetch_data_from_legacy_system(client: &reqwest::Client, token: Option<&str>) -> Result<JsonValue, ReqwestError> {
    let url = "http://legacy.com/api";
    let fut = client.get(url).bearer_auth(token.unwrap_or("")).send();
    fetch_from_api(fut).await
}

async fn process_employee_details(client: &reqwest::Client, token: Option<&str>) -> Result<JsonValue, ReqwestError> {
    let external = fetch_employee_details_from_api(client, token.as_ref()).await?;
    let third_party = fetch_data_from_third_party_api(client, token.as_ref()).await?;
    let legacy = fetch_data_from_legacy_system(client, token.as_ref()).await?;

    // Process and merge data from different sources here...

    Ok(external)
}

// Token handling functions for JWT authentication and OAuth2 authorization code flow
async fn validate_token(redis: &Redis, token: &str) -> Result<TokenData<Claims>, Error> {
    let key = redis.get::<String, _, _>(&format_args("jwt-blacklist".to_string(), token)).await?;

    if key.is_some() {
        Err(ErrorKind::InvalidToken)
    } else {
        Ok(decode::<Claims>(&token, &get_secret::<String>().unwrap(), &Validation::new(Algorithm::HS256)).map_err(|e| Error::from(e))?)
    }
}

async fn refresh_token(client: &Client, config: &OauthConfig) -> Result<Tokens, Error> {
    let oauth = Client::new(config.clone());

    match oauth.exchange_code("authorization-code", "refresh-token").await? {
        UrlAuthorization::Success { code } => {
            match client.get("http://oauth2.com/api/access_tokens").send().await?.json().await {
                Ok(JsonValue::Object(map)) if let (Some(value), Some(refresh)) = (map.get("token"), map.get("refresh_token")) => {
                    Ok(Tokens::new(&value.as_str().unwrap(), refresh.as_str()))
                }
                _ => Err(ErrorKind::InvalidToken)
            }
        },
        _ => Err(ErrorKind::InvalidToken),
    }
}

async fn handle_token_requests(client: &reqwest::Client, redis: &Redis, config: &OauthConfig, token: Option<&str>) -> Result<Tokens, Error> {
    if let Some(token) = token {
        match validate_token(&redis, token).await {
            Ok(_) => Ok(Tokens::new(token, None)),
            Err(_) => refresh_token(&client, config),
        }
    } else {
        Err(ErrorKind::InvalidToken)
    }
}

// Rocket routes for endpoints and error handling
#[rocket::main]
async fn main() -> Result<(), Error>{
    // Initialize Redis client, reqwest client, and OAuth2 configuration

    let redis_config = RedisConfig::new("redis://localhost:6379");
    let client = reqwest::Client::builder().timeout(std::time::Duration::from_secs(10)).build()?;
    let oauth_config = OauthConfig::new("client-id", "client-secret", "http://localhost:8000/callback");

    rocket::ignite()
        .manage(client)
        .mount("/", routes![index])
        .launch();

    Ok(())
}

// Rocket route handlers for endpoints and error handling
#[get("/")]
async fn index(tokens: Option<String>, client: &reqwest::Client) -> Result<&'static str, Error> {
    // Fetch and process employee details from external systems

    match handle_token_requests(&client, &redis_config.address, &oauth_config, tokens).await? {
        Ok(tokens) => {
            let data = process_employee_details(&client, Some(&tokens.access)).await?;

            // Do something with the processed data...

            Ok("Success")
        },
        Err(_) => Err(ErrorKind::InvalidToken),
    }
}
``` 
The above code is just a conceptual example, you would need to adjust and implement for your specific use case. It uses various Rust crates for tasks like Tokio for asynchronous programming, Rocket for web service framework, Serde for data serialization/deserialization, jsonwebtoken for JWT handling, OAuth2 for OAuth2 client, Redis for token storage, and reqwest for HTTP requests.
']

