['Creating a complete application with these requirements would be very complex and lengthy, but here is an example of how you might start implementing the configuration file parsing function and some related testing in C:

```c
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <netdb.h>  // for getaddrinfo()
#include <arpa/inet.h>   // for inet_ntop

#define MAX_LINE 256
#define MAX_ENDPOINT 100
#define MAX_LATENCY 1000  // in milliseconds

typedef struct {
    char name[MAX_LINE];
    char endpoint[MAX_ENDPOINT];
    int latency;  // in milliseconds
} ServiceConfig;

int validate_config(const char* filename, ServiceConfig* config) {
    FILE *file = fopen (filename , "r");
    if (file == NULL) return -1;

    char line[MAX_LINE];
    int i = 0;  // index of current service configuration

    while(fgets(line, sizeof(line), file)) {
        char *name = strtok(line, ",");
        if (name == NULL) return -2;  // malformed line

        char *endpoint = strtok(NULL, ",");
        if (endpoint == NULL) return -3;  // missing endpoint

        char *latency_str = strtok(NULL, ",");
        if (latency_str == NULL || sscanf(latency_str, "%d", &config[i].latency) != 1) return -4;  // invalid or missing latency

        // Check endpoint reachability
        struct addrinfo hints, *infoptr;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_UNSPEC;   // either IPv4 or IPv6
        hints.ai_socktype = SOCK_STREAM;
        int result = getaddrinfo(endpoint, "http", &hints, &infoptr);
        if (result != 0) return -5;  // endpoint unreachable

        freeaddrinfo(infoptr);

        strncpy(config[i].name, name, MAX_LINE);
        strncpy(config[i].endpoint, endpoint, MAX_ENDPOINT);

        i++;
    }

    fclose(file);
    return 0;
}

int main() {
    ServiceConfig config[MAX_LINE];
    int result = validate_config("config.txt", config);
    assert(result == 0);   // Assert that the configuration is valid
    printf("Configuration file parsed and validated successfully.\n");
    return 0;
}
```
For testing, you might use a library like Check (check.sourceforge.net). The following test checks whether the function correctly identifies missing fields:

```c
START_TEST(test_validate_config) {
    ServiceConfig config[MAX_LINE];
    int result = validate_config("bad-config.txt", config);
    ck_assert_int_eq(result, -2);  // Expect malformed line error code
} END_TEST
```
Please note that this is a simplified example and doesn't cover all the requirements of an API gateway such as load balancing, security features, circuit breaker pattern, or dynamic resource allocation strategy. Implementing these features would require much more complex code, possibly involving system calls to other languages (like Python for scripting), network programming, and potentially even machine learning algorithms for anomaly detection.
