    pub fn new() -> Self {
        CommandBuilder {
            command: "".to_string(),
            args: vec![],
        }
    }

    pub fn with_command(mut self, command: &str) -> Self {
        self.command = command.to_string();
        self
    }

    pub fn with_arg(mut self, arg: &str) -> Self {
        self.args.push(arg.to_string());
        self
    }

    pub fn build(&self) -> Command {
