/* Function that actually uploads file using libcurl */
int performUpload(CURL *curl, FileUploadInfo files[], int numFiles) {
   CURLcode res;
   for (int i = 0; i < numFiles; ++i) {
       FILE* hd_src = fopen(files[i].path, "rb"); 
       curl_easy_setopt(curl, CURLOPT_READDATA, hd_src);
       curl_easy_setopt(curl, CURLOPT_URL, files[i].url);
       /* Perform the request, res will get the return code */ 
       res = curl_easy_perform(curl);

       /* Check for errors */ 
       if(res != CURLE_OK) {
          LOG(LOG_ERROR, "Failed to upload file: %s. Error: %s", files[i].path, curl_easy_strerror(res));
          return -1; /* Exit thread with error code */
       }
       fclose(hd_src); /* close the local file */
   }
   return 0;
}

void uploadFilesWithLogging(FileUploadInfo files[], int numFiles) {
    if (numFiles > MAX_FILES) {
        LOG(LOG_ERROR, "Too many files. Maximum is %d", MAX_FILES);
        return;
    }

    CURL *curl = curl_easy_init();  /* Start libcurl */
    if (curl == NULL) {
        LOG(LOG_ERROR, "Failed to initialize libcurl");
        return;
    }

    for (int i = 0; i < numFiles; ++i) {
      performUpload(curl, files[i], 1); /* Assuming one file at a time */
    }

    curl_easy_cleanup(curl); /* Clean up libcurl */
}
