const std::string PAYLOAD = R"({
  "timestamp": 1645789013,
  "value": 2.718
})";

struct DeviceData {
    int timestamp;
    double value;
};

class IoTDataHandler {
public:
    void start() {
        work_ = std::make_unique<boost::asio::io_service::work>(ioService_);
        thread_ = std::thread([this](){ ioService_.run(); });

        // Load initial schema
        loadSchema(SCHEMA);
    }

    void stop() {
        work_.reset();
        thread_.join();
    }

    void handleData(const std::string& payload) {
        // Validate and parse JSON
        nlohmann::json data;
        try {
            data = nlohmann::json::parse(payload);
            if (!nlohmann::json::accept(data)) {
                throw std::runtime_error("JSON doesn't match the schema.");
            }
        } catch (const std::exception& e) {
            // Handle error here, e.g., log it and return
            return;
        }

        DeviceData deviceData = data;  // implicit conversion thanks to nlohmann::json magic

        std::lock_guard<std::shared_timed_mutex> lock(dataMutex_);
        data_.insert_or_assign(deviceData.timestamp, deviceData);
    }

    void loadSchema(const std::string& schema) {
        nlohmann::json newSchema = nlohmann::json::parse(schema);

        // Replace the current schema with a new one
        std::lock_guard<std::shared_timed_mutex> lock(schemaMutex_);
        nlohmann::json::schema_ref_cache.insert_or_assign("", newSchema);
    }

private:
    boost::asio::io_service ioService_;
    std::unique_ptr<boost::asio::io_service::work> work_;
    std::thread thread_;

    std::shared_timed_mutex schemaMutex_, dataMutex_;

    nlohmann::json currentSchema_;
    std::unordered_map<int, DeviceData> data_;  // Assuming timestamp is unique per device
};

void MQTTCallback(const std::string& payload) {
    static IoTDataHandler handler;

    // Handle the data in a separate thread
    boost::asio::post(handler.handleData, payload);
}

int main() {
    IoTDataHandler handler;
    handler.start();
    MQTTCallback(PAYLOAD);  // Simulate receiving a message from an MQTT broker

    return 0;
}
```

