using System;
using System.Threading;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public interface IConnectionManager
{
    Task<IConnection> GetConnectionAsync(string id);
}

public class ConnectionManager : IConnectionManager
{
    private readonly ConcurrentDictionary<string, Lazy<Task<IConnection>>> _connections = new ConcurrentDictionary<string, Lazy<Task<IConnection>>>();

    public Task<IConnection> GetConnectionAsync(string id)
    {
        return _connections.GetOrAdd(id, CreateLazy).Value;
    }

    private Lazy<Task<IConnection>> CreateLazy(string id)
    {
        return new Lazy<Task<IConnection>>(() => CreateConnectionAsync(id), LazyThreadSafetyMode.ExecutionAndPublication);
    }

    private async Task<IConnection> CreateConnectionAsync(string id)
    {
        var connection = new Connection();

        // You need to implement logic for creating and setting up a connection here

        return await Task.FromResult(connection);
    }
}

public interface IConnection
{
    string Id { get; }
    DateTime LastActiveTimeStamp { get; set; }
    bool IsActive { get; set; }
}

public class Connection : IConnection
{
    public string Id { get; private set; } = Guid.NewGuid().ToString();
    public DateTime LastActiveTimeStamp { get; set; } = DateTime.UtcNow;
    public bool IsActive { get; set; } = true;
}
