    std::mutex mtx;
    std::unordered_map<std::string, std::pair<int, long>> cache; // Using simple in-memory cache

    int getValue(const std::string& userId) {
        auto currentTime = std::chrono::system_clock::now();

        mtx.lock();
        if (cache.find(userId) != cache.end()) {
            const auto& entry = cache[userId];

            // If the value is expired, return stale data and schedule an update for later.
            if (entry.second < currentTime.time_since_epoch().count()) { 
