                }).detach();

                return entry.first;
            }

            mtx.unlock();
            return entry.first;
        }

        mtx.unlock();

        auto value = // Call key-value store or fallback logic here
        cache[userId] = std::make_pair(value, (currentTime + std::chrono::seconds(30)).time_since_epoch().count());

        return value;
    }

    void updateValue(const std::string& userId) { 
