```cpp
#include <iostream>
#include <string>
#include <hiredis/hiredis.h>

class UserPreferencesManager {
private:
    redisContext *_context;
public:
    UserPreferencesManager() {
        const char* hostname = "127.0.0.1";  // Change to your Redis server IP
        const int port = 6379;               // Default Redis port
        struct timeval timeout = { 1, 50000 }; // 1.5 seconds

        _context = redisConnectWithTimeout(hostname, port, timeout);

        if (_context == NULL || _context->err) {
            if (_context) {
                std::cout << "Connection error: " << _context->errstr << "\n";
                redisFree(_context);
            } else {
                std::cout << "Connection error: can't allocate redis context\n";
            }
        }
    }
    ~UserPreferencesManager() {
        redisFree(_context);
    }

    void setPreference(const std::string& userId, const std::string& key, const std::string& value) {
        std::string prefKey = "user:" + userId + ":pref:" + key;

        redisReply* reply = (redisReply*)redisCommand(_context, "SET %s %s", prefKey.c_str(), value.c_str());
        if(reply == NULL) {
            std::cout << "Failed to execute command\n";
            return;
        }

        freeReplyObject(reply);
    }

    // More methods for getPreference, deletePreference would be here.
};
```
