class TaskState {
public:
    void add(const std::string& key, const std::string& value) {
        std::unique_lock<std::shared_timed_mutex> lock(m);
        taskStates.insert({key, value});
    }

    bool remove(const std::string& key) {
        std::unique_lock<std::shared_timed_mutex> lock(m);
        return taskStates.erase(key) != 0;
    }

    std::string get(const std::string& key) const {
        std::shared_lock<std::shared_timed_mutex> lock(m);
        auto it = taskStates.find(key);

        if (it != taskStates.end())
            return it->second;

        return "";
    }

private:
    mutable std::shared_timed_mutex m;
    std::unordered_map<std::string, std::string> taskStates;
};
```
In the above code:
