```cpp
#include <mbedtls/config.h>
#include <mbedtls/ctr_drbg.h>
#include <mbedtls/entropy.h>
#include <mbedtls/ssl.h>
#include <mbedtls/x509_crt.h>
#include <mbedtls/pk.h>
#include <string>

class SecureCommunication {
public:
    // Initialize library with the given certificate and private key
    bool init(std::string cert, std::string pkey) {
        mbedtls_ssl_init(&ssl);
        mbedtls_x509_crt_parse(&certificate, (const unsigned char*)cert.c_str(), cert.size());
        mbedtls_pk_parse_key(&private_key, (const unsigned char*)pkey.c_str(), pkey.size(), NULL, 0);
    }

    // Connect to the server
    bool connect(std::string hostname) {
        mbedtls_net_connect(&server_fd, hostname.c_str(), "443", MBEDTLS_NET_PROTO_TCP);
        mbedtls_ssl_config_defaults(&conf, MBEDTLS_SSL_IS_CLIENT, MBEDTLS_SSL_TRANSPORT_STREAM, MBEDTLS_PREMASTER_RANDOM);
        mbedtls_ssl_conf_rng(&conf, mbedtls_ctr_drbg_random, &ctr_drbg);
        mbedtls_ssl_setup(&ssl, &conf);
        mbedtls_ssl_set_hostname(&ssl, hostname.c_str());
        mbedtls_ssl_set_bio(&ssl, &server_fd, mbedtls_net_send, mbedtls_net_recv, NULL);

        return mbedtls_ssl_handshake(&ssl) == 0;
    }

    // Send a message to the server
    bool send(std::string message) {
        mbedtls_ssl_write(&ssl, (const unsigned char*)message.c_str(), message.size());
    }

    // Receive a message from the server
    std::string receive() {
        unsigned char buf[1024];
        int ret = mbedtls_ssl_read(&ssl, buf, sizeof(buf));

        if (ret > 0) {
            return std::string((char*)buf, ret);
        } else {
            // error handling here
        }
    }

private:
    mbedtls_net_context server_fd;
    mbedtls_entropy_context entropy;
    mbedtls_ctr_drbg_context ctr_drbg;
    mbedtls_ssl_config conf;
    mbedtls_x509_crt certificate;
    mbedtls_pk_context private_key;
    mbedtls_ssl_context ssl;
};
```

