class AESCipher(object):
    def __init__(self, storage_service, key=None, iv=None):
        self.storage_service = storage_service
        if not key:
            self.key = Random.new().read(AES.block_size)  # Generate a secure random key
        else:
            self.key = key

        if not iv:
            self.iv = Random.new().read(AES.block_size)  # Generate a secure random IV
        else:
            self.iv = iv

    def encrypt(self, plaintext):
        cipher = AES.new(self.key, AES.MODE_CBC, self.iv)
        return cipher.encrypt(plaintext)

