#include <iostream>
#include <vector>
#include <string>
#include <fstream>
#include <map>
#include <thread>
#include <chrono>

struct AttackPattern {
    std::string name;
    int executionTime;
    int initialCooldown;
    int remainingCooldown;
    int energyCost;
    int priorityLevel;
};

class CombatEntity {
public:
    CombatEntity() {}
    ~CombatEntity() {}

    void loadAttackPattern(const AttackPattern& pattern) {
        patterns[pattern.name] = pattern;
    }

    void updateAttackPattern(const std::string& attackName, int newCooldown, int newEnergyCost, int newPriority) {
        auto it = patterns.find(attackName);
        if (it != patterns.end()) {
            it->second.initialCooldown = newCooldown;
            it->second.energyCost = newEnergyCost;
            it->second.priorityLevel = newPriority;
        }
    }

    void executeAttack() {
        AttackPattern* bestPattern = nullptr;
        for (auto& pair : patterns) {
            if (!pair.second.remainingCooldown) {
                if (bestPattern == nullptr || pair.second.priorityLevel > bestPattern->priorityLevel || 
                    (pair.second.priorityLevel == bestPattern->priorityLevel && 
                     pair.second.initialCooldown < bestPattern->initialCooldown)) {
                        bestPattern = &(pair.second);
                }
            }
        }

        if (bestPattern) {
            std::cout << "Executing attack: " << bestPattern->name << "\n";
            bestPattern->remainingCooldown = bestPattern->initialCooldown;
            consumeEnergy(bestPattern->energyCost);
        } else {
            std::cout << "No available attacks at the moment.\n";
        }
    }

private:
    void consumeEnergy(int amount) {  /* Implement this based on your API */ }

    std::map<std::string, AttackPattern> patterns;
};
```
This class represents a combat entity that can load attack patterns from an external configuration file and executes attacks based on the defined criteria. It uses a `std::map` to store attack patterns by name for efficient lookup and execution. The `executeAttack` method iterates over all available attack patterns, selecting the one with highest priority and lowest cooldown time that is ready to execute. After executing an attack, it updates its remaining cooldown time and consumes energy based on its energy cost.
