```typescript
import { BehaviorSubject } from 'rxjs';
import { ajax } from 'rxjs/ajax';
import { mergeMap, retry, catchError, map } from 'rxjs/operators';
import { Subject } from 'rxjs';

class AsyncUIUpdaterService {
  private workers: Worker[] = [];
  private taskQueue$ = new BehaviorSubject<string[]>(null);
  private updateAck$ = new Subject<{ id: string, data?: any }>();
  private token: string; // Replace with your auth mechanism.

  constructor(private targetElements: { [id: string]: HTMLElement }, workerCount: number) {
    this.initWorkers(workerCount);
    this.taskQueue$.pipe(mergeMap(ids => this.balanceTasks(ids))).subscribe();
  }

  private initWorkers(count: number): void {
    for (let i = 0; i < count; i++) {
      this.workers[i] = new Worker('worker-task.js');
      this.workers[i].onmessage = ({ data }) => this.updateAck$.next(data);
    }
  }

  private balanceTasks(ids: string[]): Subject<string> {
    const subject$ = new Subject<string>();

    ids.forEach((id, i) => {
      this.workers[i % this.workers.length].postMessage(id);
    });

    return subject$;
  }

  public async updateUIElements(ids: string[]): Promise<void> {
    this.taskQueue$.next(ids);
    // Listen to ack from main thread.
    this.updateAck$.subscribe(({ id, data }) => {
      if (data) {
        // Update UI.
        this.targetElements[id].innerText = data;
      } else {
        // Handle error scenario.
      }
    });
  }
}
