```java
import org.springframework.cloud.aws.core.region.RegionProvider;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import com.amazonaws.auth.AWSStaticCredentialsProvider;
import com.amazonaws.auth.BasicAWSCredentials;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.AmazonS3ClientBuilder;

@Configuration
public class AwsConfig {
    private final String accessKeyId = "your-access-key";
    private final String secretAccessKey = "your-secret-access-key";
    private final String regionName = "us-west-2"; // replace with your region

    @Bean
    public AmazonS3 amazonS3Client(RegionProvider regionProvider) {
        BasicAWSCredentials awsCreds = new BasicAWSCredentials(accessKeyId, secretAccessKey);

        return AmazonS3ClientBuilder.standard()
            .withRegion(regionName)
            .withCredentials(new AWSStaticCredentialsProvider(awsCreds))
            .build();
    }
}
```

This configuration sets up a basic connection to AWS S3 using the provided credentials and region. You would replace "your-access-key", "your-secret-access-key" with your actual credentials, and "us-west-2" with the correct region for you application. 

Please note this is just a very basic example. Real world application will be much complex as it requires proper error handling, configuration management, security aspects etc which are not covered here.
']

