```C#
using System;
using System.IO;
using System.Threading;
using System.Diagnostics;
using System.Net.Http;

public class DeploymentManager 
{
    private static readonly HttpClient httpClient = new HttpClient();
    private const string WEB_CONFIG_FILENAME = "web.config";
    private const int MAX_RETRIES = 5;

    public void DeployWebsite(string appName, string directoryPath, string externalServiceUrl) 
    {
        if (!Directory.Exists(directoryPath)) 
        {
            throw new DirectoryNotFoundException("Invalid directory.");
        }

        var requiredDirectories = new[] {"wwwroot", "bin", "logs"};

        foreach (var dir in requiredDirectories) 
        {
            if (!Directory.Exists(Path.Combine(directoryPath, dir))) 
            {
                throw new DirectoryNotFoundException($"Missing sub-directory: {dir}");
            }
        }

        string webConfigPath = Path.Combine(directoryPath, WEB_CONFIG_FILENAME);
        if (!File.Exists(webConfigPath)) 
        {
            throw new FileNotFoundException("No web.config found.");
        }

        for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) 
        {
            try 
            {
                if (!string.IsNullOrEmpty(externalServiceUrl)) 
                {
                    var response = httpClient.GetAsync(externalServiceUrl).Result;

                    if (!response.IsSuccessStatusCode) 
                    {
                        throw new HttpRequestException("Unable to communicate with external service.");
                    }
                }

                // Deploy the website here using Process.Start() and handling any exceptions accordingly

                return; // Successful deployment
            } 
            catch (HttpRequestException e) 
            {
                if (attempt == MAX_RETRIES) 
                {
                    throw;
                }

                Thread.Sleep(TimeSpan.FromSeconds(Math.Pow(2, attempt))); // Backoff and retry
            } 
            catch (Exception e) 
            {
                if (attempt == MAX_RETRIES) 
                {
                    throw;
                }

                Thread.Sleep(TimeSpan.FromSeconds(1)); // Re-attempt immediately
            }
        }
    }
}
```
This is a simplified example and in real use case, you would need to include more sophisticated error handling, logging mechanism, thread safety mechanisms etc. Make sure to handle exceptions correctly for concurrent access scenarios as well. 

Please note that the deployment of a web application depends heavily on the specifics of your application, so this code is just a generic starting point and might need further adjustments based on specific requirements.
']
